INSERT INTO sat_questions (question_id, external_id, vault_id, disclosed_item_id, source, program, test_type, test_type_desc, domain, primary_class_cd, skill_cd, skill_desc, difficulty, score_band_range_cd, question_type, stimulus_html, stem_html, answer_options, correct_answer, answer_keys, rationale_html, correct_answer_extracted_from_rationale, image_count, parent_template_name, parent_template_id, template_cluster_id, template_cluster_name, origin, position, answer_style, section, raw_payload, created_date, updated_date) VALUES
    ($SATQ$e5e7f264$SATQ$, $SATQ$4e5f6549-43db-44f3-bb94-e18e500d3b87$SATQ$::uuid, NULL, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Craft and Structure$SATQ$, $SATQ$CAS$SATQ$, $SATQ$WIC$SATQ$, $SATQ$Words in Context$SATQ$, $SATQ$E$SATQ$, 1, $SATQ$mcq$SATQ$, $SATQ$<p>The general store was essential to daily life in the rural United States during the 1800s because it provided the supplies that the people living in nearby communities needed. Also, the store was a <span aria-hidden="true">______</span><span class="sr-only">blank</span> of information. People socializing at the general store would share news and help spread it throughout their communities.</p>$SATQ$, $SATQ$<p>Which choice completes the text with the most logical and precise word or phrase?</p>$SATQ$, $SATQ$[{"id":"3a87b056-b20a-4f4c-a9cb-d175c4a85441","content":"<p>source</p>"},{"id":"431d6042-1e70-4dda-93f4-84306d34d148","content":"<p>rival</p>"},{"id":"31bef792-958b-42ef-b0f9-6e518370516b","content":"<p>condition</p>"},{"id":"ccf62cb4-954f-4d84-8886-37fdb63f6e67","content":"<p>waste</p>"}]$SATQ$::jsonb, $SATQ$["A"]$SATQ$::jsonb, $SATQ$["3a87b056-b20a-4f4c-a9cb-d175c4a85441"]$SATQ$::jsonb, $SATQ$<p>Choice A is the best answer because it most logically completes the text&rsquo;s discussion of the role of the general store in US rural communities during the 1800s. In this context, "source" means a place where something originates or is obtained. The text states that people would share news while socializing at the general store. This context supports the idea that the store served as a source of information in rural communities.</p><p>Choice B is incorrect because "rival" would mean competitor or opponent. The text doesn&rsquo;t indicate that the general store was a rival of anything. Instead, the text describes the general store as a place that enabled the sharing of information within rural communities. Choice C is incorrect because in this context, "condition" would mean state, circumstance, or requirement.  Although the text implies that visiting the store was helpful for acquiring information since people shared news there, it wouldn&rsquo;t make sense to say that the general store was a condition of information. Choice D is incorrect because "waste" would mean something that is unused, discarded, or spent unnecessarily, which would not make sense in context. The text describes the general store as an essential part of daily life and a place for socializing and information sharing. The store was therefore a source, not a waste, of information.</p>$SATQ$, false, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, $SATQ${"questionId":"e5e7f264","external_id":"4e5f6549-43db-44f3-bb94-e18e500d3b87","vaultid":null,"uId":"a02eab40-eabf-49a3-9372-33999c3814dd","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"CAS","domain":"Craft and Structure","skill_cd":"WIC","skill_desc":"Words in Context","difficulty":"E","score_band_range_cd":1,"type":"mcq","stimulus":"<p>The general store was essential to daily life in the rural United States during the 1800s because it provided the supplies that the people living in nearby communities needed. Also, the store was a <span aria-hidden=\"true\">______</span><span class=\"sr-only\">blank</span> of information. People socializing at the general store would share news and help spread it throughout their communities.</p>","stem":"<p>Which choice completes the text with the most logical and precise word or phrase?</p>","answerOptions":[{"id":"3a87b056-b20a-4f4c-a9cb-d175c4a85441","content":"<p>source</p>"},{"id":"431d6042-1e70-4dda-93f4-84306d34d148","content":"<p>rival</p>"},{"id":"31bef792-958b-42ef-b0f9-6e518370516b","content":"<p>condition</p>"},{"id":"ccf62cb4-954f-4d84-8886-37fdb63f6e67","content":"<p>waste</p>"}],"keys":["3a87b056-b20a-4f4c-a9cb-d175c4a85441"],"correct_answer":["A"],"rationale":"<p>Choice A is the best answer because it most logically completes the text&rsquo;s discussion of the role of the general store in US rural communities during the 1800s. In this context, \"source\" means a place where something originates or is obtained. The text states that people would share news while socializing at the general store. This context supports the idea that the store served as a source of information in rural communities.</p><p>Choice B is incorrect because \"rival\" would mean competitor or opponent. The text doesn&rsquo;t indicate that the general store was a rival of anything. Instead, the text describes the general store as a place that enabled the sharing of information within rural communities. Choice C is incorrect because in this context, \"condition\" would mean state, circumstance, or requirement.  Although the text implies that visiting the store was helpful for acquiring information since people shared news there, it wouldn&rsquo;t make sense to say that the general store was a condition of information. Choice D is incorrect because \"waste\" would mean something that is unused, discarded, or spent unnecessarily, which would not make sense in context. The text describes the general store as an essential part of daily life and a place for socializing and information sharing. The store was therefore a source, not a waste, of information.</p>","parenttemplatename":null,"parenttemplateid":null,"templateclusterid":null,"templateclustername":null,"origin":null,"position":null,"createDate":1743430669206,"updateDate":1743430669206}$SATQ$::jsonb, 1743430669206, 1743430669206),
    ($SATQ$e7247766$SATQ$, $SATQ$b4984813-1926-4366-a1fa-e1c4685e6b4e$SATQ$::uuid, $SATQ$3755cde8-c515-4c38-b49f-ba1878f02e8a$SATQ$::uuid, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Craft and Structure$SATQ$, $SATQ$CAS$SATQ$, $SATQ$TSP$SATQ$, $SATQ$Text Structure and Purpose$SATQ$, $SATQ$M$SATQ$, 5, $SATQ$mcq$SATQ$, $SATQ$<p>Horizontal gene transfer occurs when an organism of one species acquires genetic material from an organism of another species through nonreproductive means. The genetic material can then be transferred &ldquo;vertically&rdquo; in the second species&mdash;that is, through reproductive inheritance. Scientist Atma Ivancevic and her team have hypothesized infection by invertebrate parasites as a mechanism of horizontal gene transfer between vertebrate species: <span role="region" aria-label="Referenced Content"><u>while feeding, a parasite could acquire a gene from one host, then relocate to a host from a different vertebrate species and transfer the gene to it in turn.</u></span></p>$SATQ$, $SATQ$<p>Which choice best describes the function of the underlined portion in the text as a whole?</p>$SATQ$, $SATQ$[{"id":"c1ca0a1a-3b3c-402a-8903-3eb8768d86b5","content":"<p>It explains why parasites are less susceptible to horizontal gene transfer than their hosts are.</p>"},{"id":"93731870-fbea-401d-ab11-b53719a64bf3","content":"<p>It clarifies why some genes are more likely to be transferred horizontally than others are.</p>"},{"id":"ad2f7682-7a60-470c-a4bd-1c16e18820bf","content":"<p>It contrasts how horizontal gene transfer occurs among vertebrates with how it occurs among invertebrates.&nbsp;</p>"},{"id":"972b253f-1eed-417b-8823-de56ebe78ef4","content":"<p>It describes a means by which horizontal gene transfer might occur among vertebrates.</p>"}]$SATQ$::jsonb, $SATQ$["D"]$SATQ$::jsonb, $SATQ$["972b253f-1eed-417b-8823-de56ebe78ef4"]$SATQ$::jsonb, $SATQ$<p>Choice D is the best answer. The text defines horizontal gene transfer and then gives one possibility for how it happens in vertebrates (via infection by parasites). The underlined part describes how that mechanism could work. </p><p>Choice A is incorrect. The underlined portion doesn&rsquo;t do this. &nbsp;Parasites are only described as the mechanism that does the transferring, not the species that gives or receives the genes. Choice B is incorrect. The underlined portion doesn&rsquo;t do this. &nbsp;The text never discusses which genes are more likely to be transferred. Choice C is incorrect. The underlined portion doesn&rsquo;t do this. &nbsp;The text never discusses how horizontal gene transfer occurs among invertebrates. </p>$SATQ$, false, 0, $SATQ$OSP-KA-TSP-M004$SATQ$, $SATQ$$SATQ$, $SATQ$905a233e-d5a8-4b02-9925-8a7b41dde0bf$SATQ$::uuid, $SATQ$$SATQ$, $SATQ$proteus$SATQ$, $SATQ$0$SATQ$, NULL, NULL, $SATQ${"questionId":"e7247766","external_id":"b4984813-1926-4366-a1fa-e1c4685e6b4e","vaultid":"3755cde8-c515-4c38-b49f-ba1878f02e8a","uId":"de88f494-3ef6-402d-be8d-1783d9cab9fd","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"CAS","domain":"Craft and Structure","skill_cd":"TSP","skill_desc":"Text Structure and Purpose","difficulty":"M","score_band_range_cd":5,"type":"mcq","stimulus":"<p>Horizontal gene transfer occurs when an organism of one species acquires genetic material from an organism of another species through nonreproductive means. The genetic material can then be transferred &ldquo;vertically&rdquo; in the second species&mdash;that is, through reproductive inheritance. Scientist Atma Ivancevic and her team have hypothesized infection by invertebrate parasites as a mechanism of horizontal gene transfer between vertebrate species: <span role=\"region\" aria-label=\"Referenced Content\"><u>while feeding, a parasite could acquire a gene from one host, then relocate to a host from a different vertebrate species and transfer the gene to it in turn.</u></span></p>","stem":"<p>Which choice best describes the function of the underlined portion in the text as a whole?</p>","answerOptions":[{"id":"c1ca0a1a-3b3c-402a-8903-3eb8768d86b5","content":"<p>It explains why parasites are less susceptible to horizontal gene transfer than their hosts are.</p>"},{"id":"93731870-fbea-401d-ab11-b53719a64bf3","content":"<p>It clarifies why some genes are more likely to be transferred horizontally than others are.</p>"},{"id":"ad2f7682-7a60-470c-a4bd-1c16e18820bf","content":"<p>It contrasts how horizontal gene transfer occurs among vertebrates with how it occurs among invertebrates.&nbsp;</p>"},{"id":"972b253f-1eed-417b-8823-de56ebe78ef4","content":"<p>It describes a means by which horizontal gene transfer might occur among vertebrates.</p>"}],"keys":["972b253f-1eed-417b-8823-de56ebe78ef4"],"correct_answer":["D"],"rationale":"<p>Choice D is the best answer. The text defines horizontal gene transfer and then gives one possibility for how it happens in vertebrates (via infection by parasites). The underlined part describes how that mechanism could work. </p><p>Choice A is incorrect. The underlined portion doesn&rsquo;t do this. &nbsp;Parasites are only described as the mechanism that does the transferring, not the species that gives or receives the genes. Choice B is incorrect. The underlined portion doesn&rsquo;t do this. &nbsp;The text never discusses which genes are more likely to be transferred. Choice C is incorrect. The underlined portion doesn&rsquo;t do this. &nbsp;The text never discusses how horizontal gene transfer occurs among invertebrates. </p>","parenttemplatename":"OSP-KA-TSP-M004","parenttemplateid":"","templateclusterid":"905a233e-d5a8-4b02-9925-8a7b41dde0bf","templateclustername":"","origin":"proteus","position":"0","createDate":1691007959375,"updateDate":1691007959375}$SATQ$::jsonb, 1691007959375, 1691007959375),
    ($SATQ$e7b709fc$SATQ$, $SATQ$c727f0fa-b90d-4d15-90d4-ed092f4a92a0$SATQ$::uuid, $SATQ$020eaa9b-1426-4106-95ee-fdd43f58e2c4$SATQ$::uuid, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Craft and Structure$SATQ$, $SATQ$CAS$SATQ$, $SATQ$WIC$SATQ$, $SATQ$Words in Context$SATQ$, $SATQ$E$SATQ$, 2, $SATQ$mcq$SATQ$, $SATQ$<p>Archaeologists studying an ancient amphitheater in Switzerland believe that it dates back to the fourth century CE. Their discoveries of a coin made between 337 and 341 CE and era-appropriate building materials <span aria-hidden="true">______</span><span class="sr-only">blank</span> evidence for this theory.</p>$SATQ$, $SATQ$<p>Which choice completes the text with the most logical and precise word or phrase?</p>$SATQ$, $SATQ$[{"id":"1ee0b744-db25-4f74-859a-972f38563c70","content":"<p>dismiss</p>"},{"id":"119ba0df-37f3-4ad5-9f7e-ca70d723a476","content":"<p>provide</p>"},{"id":"d7807b4c-fe5e-4f2f-942e-ce0fcfa05353","content":"<p>regulate</p>"},{"id":"c197a8b4-e289-4f92-b7ef-577a5c3b3489","content":"<p>refuse</p>"}]$SATQ$::jsonb, $SATQ$["B"]$SATQ$::jsonb, $SATQ$["119ba0df-37f3-4ad5-9f7e-ca70d723a476"]$SATQ$::jsonb, $SATQ$<p>Choice B is the best answer because it most logically completes the text&rsquo;s discussion of the archaeologists&rsquo; study of the ancient amphitheater in Switzerland. In this context, &ldquo;provide&rdquo; means make available or supply. The text states that the archaeologists believe that the amphitheater dates to the fourth century CE. The text goes on to say that the archaeologists discovered a coin made between 337 and 341 CE (that is, made during the fourth century CE) and building materials appropriate to the era in question. This context suggests that these discoveries provide evidence for the archaeologists&rsquo; theory about the dating of the amphitheater.&nbsp;</p><p>Choice A is incorrect because the archaeologists&rsquo; discoveries are presented as supplying evidence in favor of their theory about the dating of the amphitheater, not something that would &ldquo;dismiss,&rdquo; or reject serious consideration of, evidence for that theory.&nbsp;Choice C is incorrect because nothing in the text suggests that the archaeologists&rsquo; discoveries would &ldquo;regulate,&rdquo; or govern or bring order to, evidence for the archaeologists&rsquo; theory about the dating of the amphitheater. The discoveries are presented as supplying evidence for the archaeologists&rsquo; theory, not as changing how evidence for the theory is controlled or ordered. Choice D is incorrect because the archaeologists&rsquo; discoveries are presented as supplying evidence in favor of their theory about the dating of the amphitheater, not something that would &ldquo;refuse,&rdquo; or be unwilling to accept, evidence for the archaeologists&rsquo; theory.&nbsp;</p>$SATQ$, false, 0, $SATQ$OSP-055-WIC$SATQ$, $SATQ$$SATQ$, $SATQ$a543575e-bc0f-43d8-ba15-3dbd62ae08ac$SATQ$::uuid, $SATQ$$SATQ$, $SATQ$proteus$SATQ$, $SATQ$0$SATQ$, NULL, NULL, $SATQ${"questionId":"e7b709fc","external_id":"c727f0fa-b90d-4d15-90d4-ed092f4a92a0","vaultid":"020eaa9b-1426-4106-95ee-fdd43f58e2c4","uId":"e0d221d7-c323-4f82-8aeb-2c31c4163a64","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"CAS","domain":"Craft and Structure","skill_cd":"WIC","skill_desc":"Words in Context","difficulty":"E","score_band_range_cd":2,"type":"mcq","stimulus":"<p>Archaeologists studying an ancient amphitheater in Switzerland believe that it dates back to the fourth century CE. Their discoveries of a coin made between 337 and 341 CE and era-appropriate building materials <span aria-hidden=\"true\">______</span><span class=\"sr-only\">blank</span> evidence for this theory.</p>","stem":"<p>Which choice completes the text with the most logical and precise word or phrase?</p>","answerOptions":[{"id":"1ee0b744-db25-4f74-859a-972f38563c70","content":"<p>dismiss</p>"},{"id":"119ba0df-37f3-4ad5-9f7e-ca70d723a476","content":"<p>provide</p>"},{"id":"d7807b4c-fe5e-4f2f-942e-ce0fcfa05353","content":"<p>regulate</p>"},{"id":"c197a8b4-e289-4f92-b7ef-577a5c3b3489","content":"<p>refuse</p>"}],"keys":["119ba0df-37f3-4ad5-9f7e-ca70d723a476"],"correct_answer":["B"],"rationale":"<p>Choice B is the best answer because it most logically completes the text&rsquo;s discussion of the archaeologists&rsquo; study of the ancient amphitheater in Switzerland. In this context, &ldquo;provide&rdquo; means make available or supply. The text states that the archaeologists believe that the amphitheater dates to the fourth century CE. The text goes on to say that the archaeologists discovered a coin made between 337 and 341 CE (that is, made during the fourth century CE) and building materials appropriate to the era in question. This context suggests that these discoveries provide evidence for the archaeologists&rsquo; theory about the dating of the amphitheater.&nbsp;</p><p>Choice A is incorrect because the archaeologists&rsquo; discoveries are presented as supplying evidence in favor of their theory about the dating of the amphitheater, not something that would &ldquo;dismiss,&rdquo; or reject serious consideration of, evidence for that theory.&nbsp;Choice C is incorrect because nothing in the text suggests that the archaeologists&rsquo; discoveries would &ldquo;regulate,&rdquo; or govern or bring order to, evidence for the archaeologists&rsquo; theory about the dating of the amphitheater. The discoveries are presented as supplying evidence for the archaeologists&rsquo; theory, not as changing how evidence for the theory is controlled or ordered. Choice D is incorrect because the archaeologists&rsquo; discoveries are presented as supplying evidence in favor of their theory about the dating of the amphitheater, not something that would &ldquo;refuse,&rdquo; or be unwilling to accept, evidence for the archaeologists&rsquo; theory.&nbsp;</p>","parenttemplatename":"OSP-055-WIC","parenttemplateid":"","templateclusterid":"a543575e-bc0f-43d8-ba15-3dbd62ae08ac","templateclustername":"","origin":"proteus","position":"0","createDate":1691007959324,"updateDate":1691007959324}$SATQ$::jsonb, 1691007959324, 1691007959324),
    ($SATQ$e7d37666$SATQ$, $SATQ$19bfac22-c7f1-44c5-ad77-cd2e8185eb37$SATQ$::uuid, $SATQ$278229e6-53d1-4ca7-81d2-02267a349682$SATQ$::uuid, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Craft and Structure$SATQ$, $SATQ$CAS$SATQ$, $SATQ$WIC$SATQ$, $SATQ$Words in Context$SATQ$, $SATQ$H$SATQ$, 6, $SATQ$mcq$SATQ$, $SATQ$<p>It is by no means <span aria-hidden="true">______</span><span class="sr-only">blank</span> to recognize the influence of Dutch painter Hieronymus Bosch on Ali Banisadr&rsquo;s paintings; indeed, Banisadr himself cites Bosch as an inspiration. However, some scholars have suggested that the ancient Mesopotamian poem <em>Epic of Gilgamesh</em> may have had a far greater impact on Banisadr&rsquo;s work.</p>$SATQ$, $SATQ$<p>Which choice completes the text with the most logical and precise word or phrase?</p>$SATQ$, $SATQ$[{"id":"19e4fe70-7d1d-4902-879c-b6539243446b","content":"<p>substantial</p>"},{"id":"414b1cf8-c67e-4687-9731-df3fb2fdca85","content":"<p>satisfying</p>"},{"id":"78733f7c-69e7-486b-8ac5-17fae92dc7f7","content":"<p>unimportant</p>"},{"id":"3bb9e553-1e06-4717-82d6-51ad97cd6e5d","content":"<p>appropriate</p>"}]$SATQ$::jsonb, $SATQ$["C"]$SATQ$::jsonb, $SATQ$["78733f7c-69e7-486b-8ac5-17fae92dc7f7"]$SATQ$::jsonb, $SATQ$<p>Choice C is the best answer because it most logically completes the sentence about the influences on Banisadr&rsquo;s work. In context, &ldquo;It is by no means&rdquo; followed by &ldquo;unimportant&rdquo; conveys how it is relevant to recognize Bosch&rsquo;s influence on Banisadr. The text points out that the artist himself cites Bosch as an inspiration, and then goes on to claim that <em>The Epic of Gilgamesh</em> has had a more significant influence than Bosch.&nbsp;</p><p>Choice A is incorrect because &ldquo;substantial,&rdquo; which means weighty or meaningful, incorrectly suggests that it wouldn&rsquo;t be meaningful to acknowledge Bosch&rsquo;s influence on Banisadr. The phrase &ldquo;indeed, Banisadr himself cites Bosch as an inspiration&rdquo; doesn&rsquo;t support this suggestion.&nbsp;Choice B is incorrect because &ldquo;satisfying,&rdquo; which means pleasing, incorrectly suggests that it wouldn&rsquo;t be pleasing to acknowledge Bosch&rsquo;s influence on Banisadr. The phrase &ldquo;indeed, Banisadr himself cites Bosch as an inspiration&rdquo; doesn&rsquo;t support this suggestion.&nbsp;Choice D is incorrect because &ldquo;appropriate,&rdquo; which means suitable, incorrectly suggests that it wouldn&rsquo;t be proper to acknowledge Bosch&rsquo;s influence on Banisadr. The phrase &ldquo;indeed, Banisadr himself cites Bosch as an inspiration&rdquo; doesn&rsquo;t support this suggestion.&nbsp;</p>$SATQ$, false, 0, $SATQ$OSP-981-WIC$SATQ$, $SATQ$$SATQ$, $SATQ$b8fc1844-1cbf-4ee4-86a7-0b7fb145821b$SATQ$::uuid, $SATQ$$SATQ$, $SATQ$proteus$SATQ$, $SATQ$0$SATQ$, NULL, NULL, $SATQ${"questionId":"e7d37666","external_id":"19bfac22-c7f1-44c5-ad77-cd2e8185eb37","vaultid":"278229e6-53d1-4ca7-81d2-02267a349682","uId":"9452cb80-df69-4ac3-8e34-ede1a153cae8","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"CAS","domain":"Craft and Structure","skill_cd":"WIC","skill_desc":"Words in Context","difficulty":"H","score_band_range_cd":6,"type":"mcq","stimulus":"<p>It is by no means <span aria-hidden=\"true\">______</span><span class=\"sr-only\">blank</span> to recognize the influence of Dutch painter Hieronymus Bosch on Ali Banisadr&rsquo;s paintings; indeed, Banisadr himself cites Bosch as an inspiration. However, some scholars have suggested that the ancient Mesopotamian poem <em>Epic of Gilgamesh</em> may have had a far greater impact on Banisadr&rsquo;s work.</p>","stem":"<p>Which choice completes the text with the most logical and precise word or phrase?</p>","answerOptions":[{"id":"19e4fe70-7d1d-4902-879c-b6539243446b","content":"<p>substantial</p>"},{"id":"414b1cf8-c67e-4687-9731-df3fb2fdca85","content":"<p>satisfying</p>"},{"id":"78733f7c-69e7-486b-8ac5-17fae92dc7f7","content":"<p>unimportant</p>"},{"id":"3bb9e553-1e06-4717-82d6-51ad97cd6e5d","content":"<p>appropriate</p>"}],"keys":["78733f7c-69e7-486b-8ac5-17fae92dc7f7"],"correct_answer":["C"],"rationale":"<p>Choice C is the best answer because it most logically completes the sentence about the influences on Banisadr&rsquo;s work. In context, &ldquo;It is by no means&rdquo; followed by &ldquo;unimportant&rdquo; conveys how it is relevant to recognize Bosch&rsquo;s influence on Banisadr. The text points out that the artist himself cites Bosch as an inspiration, and then goes on to claim that <em>The Epic of Gilgamesh</em> has had a more significant influence than Bosch.&nbsp;</p><p>Choice A is incorrect because &ldquo;substantial,&rdquo; which means weighty or meaningful, incorrectly suggests that it wouldn&rsquo;t be meaningful to acknowledge Bosch&rsquo;s influence on Banisadr. The phrase &ldquo;indeed, Banisadr himself cites Bosch as an inspiration&rdquo; doesn&rsquo;t support this suggestion.&nbsp;Choice B is incorrect because &ldquo;satisfying,&rdquo; which means pleasing, incorrectly suggests that it wouldn&rsquo;t be pleasing to acknowledge Bosch&rsquo;s influence on Banisadr. The phrase &ldquo;indeed, Banisadr himself cites Bosch as an inspiration&rdquo; doesn&rsquo;t support this suggestion.&nbsp;Choice D is incorrect because &ldquo;appropriate,&rdquo; which means suitable, incorrectly suggests that it wouldn&rsquo;t be proper to acknowledge Bosch&rsquo;s influence on Banisadr. The phrase &ldquo;indeed, Banisadr himself cites Bosch as an inspiration&rdquo; doesn&rsquo;t support this suggestion.&nbsp;</p>","parenttemplatename":"OSP-981-WIC","parenttemplateid":"","templateclusterid":"b8fc1844-1cbf-4ee4-86a7-0b7fb145821b","templateclustername":"","origin":"proteus","position":"0","createDate":1691007959358,"updateDate":1691007959358}$SATQ$::jsonb, 1691007959358, 1691007959358),
    ($SATQ$e818241b$SATQ$, $SATQ$7fa24036-c896-44c1-ae1b-2a26f55b16f9$SATQ$::uuid, NULL, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Craft and Structure$SATQ$, $SATQ$CAS$SATQ$, $SATQ$TSP$SATQ$, $SATQ$Text Structure and Purpose$SATQ$, $SATQ$H$SATQ$, 6, $SATQ$mcq$SATQ$, $SATQ$<p>Astronomers are confident that the star Betelgeuse will eventually consume all the helium in its core and explode in a supernova. <span role="region" aria-label="Referenced Content"><u>They are much less confident, however, about when this will happen, since that depends on internal characteristics of Betelgeuse that are largely unknown.</u></span> Astrophysicist Sarafina El-Badry Nance and colleagues recently investigated whether acoustic waves in the star could be used to determine internal stellar states but concluded that this method could not sufficiently reveal Betelgeuse&rsquo;s internal characteristics to allow its evolutionary state to be firmly fixed.</p>$SATQ$, $SATQ$<p>Which choice best describes the function of the second sentence in the overall structure of the text?</p>$SATQ$, $SATQ$[{"id":"32f0a0f2-365c-466c-835d-cf2190cd8ecb","content":"<p>It describes a serious limitation of the method used by Nance and colleagues.&nbsp;</p>"},{"id":"84cf98d0-c36b-4ba0-80c7-335b0b0a75e2","content":"<p>It presents the central finding reported by Nance and colleagues.&nbsp;</p>"},{"id":"59a4bad3-1ca5-4914-b4ff-cf679d328815","content":"<p>It identifies the problem that Nance and colleagues attempted to solve but did not.</p>"},{"id":"6318bcc1-0725-42c7-b8af-6aa09c193294","content":"<p>It explains how the work of Nance and colleagues was received by others in the field.&nbsp;</p>"}]$SATQ$::jsonb, $SATQ$["C"]$SATQ$::jsonb, $SATQ$["59a4bad3-1ca5-4914-b4ff-cf679d328815"]$SATQ$::jsonb, $SATQ$<p>Choice C is the best answer because it best describes how the second sentence functions in the text as a whole. The first sentence establishes something astronomers believe with some certainty: that Betelgeuse will explode in a supernova. The second sentence then introduces a problem: astronomers aren&rsquo;t certain <em>when </em>Betelgeuse will explode because they don&rsquo;t have enough information about the star&rsquo;s internal characteristics. Finally, the third sentence indicates that researcher Sarafina El-Badry Nance and colleagues investigated a possible method of obtaining the necessary information about Betelgeuse&rsquo;s internal characteristics, though they found that the method wouldn&rsquo;t be sufficient. Thus, the function of the second sentence is to identify the problem that Nance and colleagues attempted to solve but didn&rsquo;t.</p><p>Choice A is incorrect because the second sentence introduces the general problem Nance and colleagues hoped to solve, not a serious limitation of how Nance and colleagues tried to solve it. It is the third sentence that introduces Nance and colleagues, but no serious limitation of their approach to studying a method of determining internal stellar states is described. Choice B is incorrect because the second sentence introduces the general problem Nance and colleagues hoped to solve, not the central finding they ultimately reported. It is the third sentence that presents Nance and colleagues&rsquo; conclusion that a potential method for determining internal stellar states would be insufficient. Choice D is incorrect because the second sentence doesn&rsquo;t indicate how other astronomers or astrophysicists responded to the work done by Nance and colleagues; the text doesn&rsquo;t address this information at all.</p>$SATQ$, false, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, $SATQ${"questionId":"e818241b","external_id":"7fa24036-c896-44c1-ae1b-2a26f55b16f9","vaultid":null,"uId":"0c0f5772-1466-45bb-9070-8e471968273b","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"CAS","domain":"Craft and Structure","skill_cd":"TSP","skill_desc":"Text Structure and Purpose","difficulty":"H","score_band_range_cd":6,"type":"mcq","stimulus":"<p>Astronomers are confident that the star Betelgeuse will eventually consume all the helium in its core and explode in a supernova. <span role=\"region\" aria-label=\"Referenced Content\"><u>They are much less confident, however, about when this will happen, since that depends on internal characteristics of Betelgeuse that are largely unknown.</u></span> Astrophysicist Sarafina El-Badry Nance and colleagues recently investigated whether acoustic waves in the star could be used to determine internal stellar states but concluded that this method could not sufficiently reveal Betelgeuse&rsquo;s internal characteristics to allow its evolutionary state to be firmly fixed.</p>","stem":"<p>Which choice best describes the function of the second sentence in the overall structure of the text?</p>","answerOptions":[{"id":"32f0a0f2-365c-466c-835d-cf2190cd8ecb","content":"<p>It describes a serious limitation of the method used by Nance and colleagues.&nbsp;</p>"},{"id":"84cf98d0-c36b-4ba0-80c7-335b0b0a75e2","content":"<p>It presents the central finding reported by Nance and colleagues.&nbsp;</p>"},{"id":"59a4bad3-1ca5-4914-b4ff-cf679d328815","content":"<p>It identifies the problem that Nance and colleagues attempted to solve but did not.</p>"},{"id":"6318bcc1-0725-42c7-b8af-6aa09c193294","content":"<p>It explains how the work of Nance and colleagues was received by others in the field.&nbsp;</p>"}],"keys":["59a4bad3-1ca5-4914-b4ff-cf679d328815"],"correct_answer":["C"],"rationale":"<p>Choice C is the best answer because it best describes how the second sentence functions in the text as a whole. The first sentence establishes something astronomers believe with some certainty: that Betelgeuse will explode in a supernova. The second sentence then introduces a problem: astronomers aren&rsquo;t certain <em>when </em>Betelgeuse will explode because they don&rsquo;t have enough information about the star&rsquo;s internal characteristics. Finally, the third sentence indicates that researcher Sarafina El-Badry Nance and colleagues investigated a possible method of obtaining the necessary information about Betelgeuse&rsquo;s internal characteristics, though they found that the method wouldn&rsquo;t be sufficient. Thus, the function of the second sentence is to identify the problem that Nance and colleagues attempted to solve but didn&rsquo;t.</p><p>Choice A is incorrect because the second sentence introduces the general problem Nance and colleagues hoped to solve, not a serious limitation of how Nance and colleagues tried to solve it. It is the third sentence that introduces Nance and colleagues, but no serious limitation of their approach to studying a method of determining internal stellar states is described. Choice B is incorrect because the second sentence introduces the general problem Nance and colleagues hoped to solve, not the central finding they ultimately reported. It is the third sentence that presents Nance and colleagues&rsquo; conclusion that a potential method for determining internal stellar states would be insufficient. Choice D is incorrect because the second sentence doesn&rsquo;t indicate how other astronomers or astrophysicists responded to the work done by Nance and colleagues; the text doesn&rsquo;t address this information at all.</p>","parenttemplatename":null,"parenttemplateid":null,"templateclusterid":null,"templateclustername":null,"origin":null,"position":null,"createDate":1691007959311,"updateDate":1691007959311}$SATQ$::jsonb, 1691007959311, 1691007959311),
    ($SATQ$e8c26398$SATQ$, $SATQ$575dc2a9-68a2-4c57-80be-8e72eb84c207$SATQ$::uuid, $SATQ$80ea87b2-020b-4970-8fa5-422e8d65cf55$SATQ$::uuid, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Craft and Structure$SATQ$, $SATQ$CAS$SATQ$, $SATQ$WIC$SATQ$, $SATQ$Words in Context$SATQ$, $SATQ$M$SATQ$, 4, $SATQ$mcq$SATQ$, $SATQ$<p>To develop a method for measuring snow depth with laser beams, NASA physicist Yongxiang Hu relied on <span aria-hidden="true">______</span><span class="sr-only">blank</span>; identifying broad similarities between&nbsp;two seemingly different phenomena, Hu used information about how ants move inside colonies to calculate how the particles of light that make up laser beams travel through snow.</p>$SATQ$, $SATQ$<p>Which choice completes the text with the most logical and precise word or phrase?</p>$SATQ$, $SATQ$[{"id":"90c02e02-3f93-4a2f-8919-06a6c12d1e48","content":"<p>a collaboration</p>"},{"id":"f6b843b0-c891-4e54-b626-eba655517b24","content":"<p>an accessory</p>"},{"id":"f32f5247-eb65-42f8-9180-a917bd9706f0","content":"<p>a contradiction</p>"},{"id":"d66962c6-93f9-481e-8d3c-e9b84c8483de","content":"<p>an analogy</p>"}]$SATQ$::jsonb, $SATQ$["D"]$SATQ$::jsonb, $SATQ$["d66962c6-93f9-481e-8d3c-e9b84c8483de"]$SATQ$::jsonb, $SATQ$<p>Choice D is the best answer. The text after the semicolon tells us that Hu "identif[ied] broad similarities between two seemingly different phenomena," comparing ants with light particles. Since an analogy seeks similarities between seemingly unrelated phenomena, this fits the context perfectly.</p><p>Choice A is incorrect. "A collaboration" refers to "an act of working with others," but what comes after the semicolon doesn&rsquo;t describe collaboration with other researchers. Instead, it shows a comparison between two different (but ultimately similar) scientific phenomena. Choice B is incorrect. "An accessory" can refer to "something added to increase attractiveness or usefulness." No accessories are described in this text. Choice C is incorrect. "A contradiction" means "a set of ideas or things that are opposed to or inconsistent with each other." The text describes how Hu used the similarity between ant and light particle movement to develop his method, so a word that refers to difference would not make sense here.</p>$SATQ$, false, 0, $SATQ$OSP-KA-WIC-M010$SATQ$, $SATQ$$SATQ$, $SATQ$62191d7c-719f-4aca-a94a-1a79fc7111f0$SATQ$::uuid, $SATQ$$SATQ$, $SATQ$proteus$SATQ$, $SATQ$0$SATQ$, NULL, NULL, $SATQ${"questionId":"e8c26398","external_id":"575dc2a9-68a2-4c57-80be-8e72eb84c207","vaultid":"80ea87b2-020b-4970-8fa5-422e8d65cf55","uId":"5c7166c5-eee0-41db-8e42-8cca27180738","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"CAS","domain":"Craft and Structure","skill_cd":"WIC","skill_desc":"Words in Context","difficulty":"M","score_band_range_cd":4,"type":"mcq","stimulus":"<p>To develop a method for measuring snow depth with laser beams, NASA physicist Yongxiang Hu relied on <span aria-hidden=\"true\">______</span><span class=\"sr-only\">blank</span>; identifying broad similarities between&nbsp;two seemingly different phenomena, Hu used information about how ants move inside colonies to calculate how the particles of light that make up laser beams travel through snow.</p>","stem":"<p>Which choice completes the text with the most logical and precise word or phrase?</p>","answerOptions":[{"id":"90c02e02-3f93-4a2f-8919-06a6c12d1e48","content":"<p>a collaboration</p>"},{"id":"f6b843b0-c891-4e54-b626-eba655517b24","content":"<p>an accessory</p>"},{"id":"f32f5247-eb65-42f8-9180-a917bd9706f0","content":"<p>a contradiction</p>"},{"id":"d66962c6-93f9-481e-8d3c-e9b84c8483de","content":"<p>an analogy</p>"}],"keys":["d66962c6-93f9-481e-8d3c-e9b84c8483de"],"correct_answer":["D"],"rationale":"<p>Choice D is the best answer. The text after the semicolon tells us that Hu \"identif[ied] broad similarities between two seemingly different phenomena,\" comparing ants with light particles. Since an analogy seeks similarities between seemingly unrelated phenomena, this fits the context perfectly.</p><p>Choice A is incorrect. \"A collaboration\" refers to \"an act of working with others,\" but what comes after the semicolon doesn&rsquo;t describe collaboration with other researchers. Instead, it shows a comparison between two different (but ultimately similar) scientific phenomena. Choice B is incorrect. \"An accessory\" can refer to \"something added to increase attractiveness or usefulness.\" No accessories are described in this text. Choice C is incorrect. \"A contradiction\" means \"a set of ideas or things that are opposed to or inconsistent with each other.\" The text describes how Hu used the similarity between ant and light particle movement to develop his method, so a word that refers to difference would not make sense here.</p>","parenttemplatename":"OSP-KA-WIC-M010","parenttemplateid":"","templateclusterid":"62191d7c-719f-4aca-a94a-1a79fc7111f0","templateclustername":"","origin":"proteus","position":"0","createDate":1691007959378,"updateDate":1691007959378}$SATQ$::jsonb, 1691007959378, 1691007959378),
    ($SATQ$e8fb0744$SATQ$, $SATQ$283479b2-e229-4d1d-b4f5-b22b6711cc09$SATQ$::uuid, $SATQ$035f9cb0-835a-4339-8d61-514d6c505a1e$SATQ$::uuid, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Craft and Structure$SATQ$, $SATQ$CAS$SATQ$, $SATQ$WIC$SATQ$, $SATQ$Words in Context$SATQ$, $SATQ$H$SATQ$, 7, $SATQ$mcq$SATQ$, $SATQ$<p>As an undergraduate researcher in anthropology, Jennifer C. Chen contributed to a groundbreaking study challenging the accepted view that among prehistoric peoples, female participation in hunting was <span aria-hidden="true">______</span><span class="sr-only">blank</span>. The research team&rsquo;s review of data from late Pleistocene and early Holocene burials in the Americas revealed that, in fact, as many as half of the hunters in those populations were female.</p>$SATQ$, $SATQ$<p>Which choice completes the text with the most logical and precise word or phrase?</p>$SATQ$, $SATQ$[{"id":"12f28168-2891-42eb-b405-9a34f4209fde","content":"<p>inevitable</p>"},{"id":"5166d705-73e6-4127-9bb5-6d911981fc26","content":"<p>satisfactory</p>"},{"id":"c6e57e15-5332-4923-a95b-eaf7014f8024","content":"<p>negligible</p>"},{"id":"6e8f2478-010f-4e8d-aa5c-7ab499772d0e","content":"<p>commonplace</p>"}]$SATQ$::jsonb, $SATQ$["C"]$SATQ$::jsonb, $SATQ$["c6e57e15-5332-4923-a95b-eaf7014f8024"]$SATQ$::jsonb, $SATQ$<p>Choice C is the best answer because it most logically completes the text&rsquo;s discussion of the study of female participation in hunting among prehistoric peoples. In this context, &ldquo;negligible&rdquo; means not significant enough to be worth considering. The text says that the study challenged the accepted view of female participation in hunting among prehistoric peoples. The text goes on to say that the researchers found that &ldquo;in fact, as many as half&rdquo; the hunters in the groups studied were female. The phrase &ldquo;in fact&rdquo; establishes a contrast indicating that the finding that as many as half the hunters were female differs from the accepted view. This context suggests, then, that the accepted view is that female participation in hunting was negligible.&nbsp;</p><p>Choice A is incorrect because the text indicates that the study challenged the accepted view by showing that as many as half of hunters among prehistoric peoples were female, which suggests that the accepted view is that female participation was low, not that female participation was &ldquo;inevitable,&rdquo; or unavoidable. Nothing in the text suggests that the accepted view is that prehistoric peoples could not avoid female participation in hunting.&nbsp;Choice B is incorrect because nothing in the text suggests that the accepted view of female participation in hunting among prehistoric peoples is that such participation was &ldquo;satisfactory,&rdquo; or sufficient to meet a requirement or demand. There is no information in the text about any demands or requirements regarding female participation in hunting, let alone any information about how much female participation in hunting would be enough to satisfy those demands or requirements. Instead, the text indicates that the study challenged the accepted view by showing that as many as half the hunters in the groups studied were female, suggesting that the accepted view is that female participation in hunting was low.&nbsp;Choice D is incorrect because the text indicates that the study challenged the accepted view by showing that as many as half of hunters among the prehistoric peoples studied were female, which suggests that the accepted view is that female participation was low, not that female participation was &ldquo;commonplace,&rdquo; or ordinary or unremarkable. Although the study under discussion suggests that female participation may have been commonplace, that study is presented as challenging the accepted view, not as reinforcing the accepted view.&nbsp;</p>$SATQ$, false, 0, $SATQ$OSP-930-WIC$SATQ$, $SATQ$$SATQ$, $SATQ$4950aee1-dd85-49f4-ae77-5ee0ae5cedc5$SATQ$::uuid, $SATQ$$SATQ$, $SATQ$proteus$SATQ$, $SATQ$0$SATQ$, NULL, NULL, $SATQ${"questionId":"e8fb0744","external_id":"283479b2-e229-4d1d-b4f5-b22b6711cc09","vaultid":"035f9cb0-835a-4339-8d61-514d6c505a1e","uId":"fd56688d-8a60-43ce-b826-491924820729","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"CAS","domain":"Craft and Structure","skill_cd":"WIC","skill_desc":"Words in Context","difficulty":"H","score_band_range_cd":7,"type":"mcq","stimulus":"<p>As an undergraduate researcher in anthropology, Jennifer C. Chen contributed to a groundbreaking study challenging the accepted view that among prehistoric peoples, female participation in hunting was <span aria-hidden=\"true\">______</span><span class=\"sr-only\">blank</span>. The research team&rsquo;s review of data from late Pleistocene and early Holocene burials in the Americas revealed that, in fact, as many as half of the hunters in those populations were female.</p>","stem":"<p>Which choice completes the text with the most logical and precise word or phrase?</p>","answerOptions":[{"id":"12f28168-2891-42eb-b405-9a34f4209fde","content":"<p>inevitable</p>"},{"id":"5166d705-73e6-4127-9bb5-6d911981fc26","content":"<p>satisfactory</p>"},{"id":"c6e57e15-5332-4923-a95b-eaf7014f8024","content":"<p>negligible</p>"},{"id":"6e8f2478-010f-4e8d-aa5c-7ab499772d0e","content":"<p>commonplace</p>"}],"keys":["c6e57e15-5332-4923-a95b-eaf7014f8024"],"correct_answer":["C"],"rationale":"<p>Choice C is the best answer because it most logically completes the text&rsquo;s discussion of the study of female participation in hunting among prehistoric peoples. In this context, &ldquo;negligible&rdquo; means not significant enough to be worth considering. The text says that the study challenged the accepted view of female participation in hunting among prehistoric peoples. The text goes on to say that the researchers found that &ldquo;in fact, as many as half&rdquo; the hunters in the groups studied were female. The phrase &ldquo;in fact&rdquo; establishes a contrast indicating that the finding that as many as half the hunters were female differs from the accepted view. This context suggests, then, that the accepted view is that female participation in hunting was negligible.&nbsp;</p><p>Choice A is incorrect because the text indicates that the study challenged the accepted view by showing that as many as half of hunters among prehistoric peoples were female, which suggests that the accepted view is that female participation was low, not that female participation was &ldquo;inevitable,&rdquo; or unavoidable. Nothing in the text suggests that the accepted view is that prehistoric peoples could not avoid female participation in hunting.&nbsp;Choice B is incorrect because nothing in the text suggests that the accepted view of female participation in hunting among prehistoric peoples is that such participation was &ldquo;satisfactory,&rdquo; or sufficient to meet a requirement or demand. There is no information in the text about any demands or requirements regarding female participation in hunting, let alone any information about how much female participation in hunting would be enough to satisfy those demands or requirements. Instead, the text indicates that the study challenged the accepted view by showing that as many as half the hunters in the groups studied were female, suggesting that the accepted view is that female participation in hunting was low.&nbsp;Choice D is incorrect because the text indicates that the study challenged the accepted view by showing that as many as half of hunters among the prehistoric peoples studied were female, which suggests that the accepted view is that female participation was low, not that female participation was &ldquo;commonplace,&rdquo; or ordinary or unremarkable. Although the study under discussion suggests that female participation may have been commonplace, that study is presented as challenging the accepted view, not as reinforcing the accepted view.&nbsp;</p>","parenttemplatename":"OSP-930-WIC","parenttemplateid":"","templateclusterid":"4950aee1-dd85-49f4-ae77-5ee0ae5cedc5","templateclustername":"","origin":"proteus","position":"0","createDate":1691007959356,"updateDate":1691007959356}$SATQ$::jsonb, 1691007959356, 1691007959356),
    ($SATQ$e929fe98$SATQ$, $SATQ$efc08b9d-1d6b-407d-bb5d-8f6c5cc24bd9$SATQ$::uuid, $SATQ$99fe354c-3769-400f-a5ef-60f7a6b514b6$SATQ$::uuid, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Craft and Structure$SATQ$, $SATQ$CAS$SATQ$, $SATQ$TSP$SATQ$, $SATQ$Text Structure and Purpose$SATQ$, $SATQ$E$SATQ$, 3, $SATQ$mcq$SATQ$, $SATQ$<p>Composer Florence Price won first place for her score Symphony in E Minor at the 1932 Wanamaker Foundation Awards. The piece was performed the following year by the Chicago Symphony Orchestra, a significant recognition of its quality. Price continued to compose many musical pieces throughout her career, blending traditional Black spirituals with classical European Romantic musical traditions. In recent years, Price&rsquo;s concertos and symphonies have been performed and recorded by several major orchestras, further preserving her work for others to enjoy.</p>$SATQ$, $SATQ$<p>Which choice best states the main purpose of the text?</p>$SATQ$, $SATQ$[{"id":"3602e1b6-9da4-4d45-a2a8-ccaf1ef4d981","content":"<p>To provide examples of Price&rsquo;s importance as a composer</p>"},{"id":"cde7b78a-6815-4e5a-ab11-506a53463873","content":"<p>To argue that more major orchestras should perform Price&rsquo;s compositions</p>"},{"id":"8456c31c-fa8b-4395-873f-9e7f982f8e73","content":"<p>To describe the musical styles that inspired many of Price&rsquo;s symphonies</p>"},{"id":"c87e1649-a068-4967-b2c4-158078dd8992","content":"<p>To compare Price&rsquo;s scores with those of classical European composers</p>"}]$SATQ$::jsonb, $SATQ$["A"]$SATQ$::jsonb, $SATQ$["3602e1b6-9da4-4d45-a2a8-ccaf1ef4d981"]$SATQ$::jsonb, $SATQ$<p>Choice A is the best answer. The text provides an overview of Florence Price&rsquo;s importance by describing her success at the 1932 Wanamaker Foundation Awards, her blending of Black spirituals and classical European Romantic musical traditions, and the recent performances and recordings of her concertos and symphonies by major orchestras. </p><p>Choice B is incorrect. The text does mention that Price&rsquo;s compositions have been performed and recorded by major orchestras, but it doesn&rsquo;t argue that more orchestras should do so. Choice C is incorrect. The text does mention the blending of Black spirituals and classical European Romantic musical traditions, but only briefly, as part of a broader overview of Price&rsquo;s career. Choice D is incorrect. The text mentions Price&rsquo;s blending of Black spirituals with classical European Romantic musical traditions, but it doesn&rsquo;t directly compare Price&rsquo;s scores with those of classical European composers. </p>$SATQ$, false, 0, $SATQ$OSP-KA-TSP-M006$SATQ$, $SATQ$$SATQ$, $SATQ$f04a68b8-2d50-45f9-a2d5-d3098ba44805$SATQ$::uuid, $SATQ$$SATQ$, $SATQ$proteus$SATQ$, $SATQ$0$SATQ$, NULL, NULL, $SATQ${"questionId":"e929fe98","external_id":"efc08b9d-1d6b-407d-bb5d-8f6c5cc24bd9","vaultid":"99fe354c-3769-400f-a5ef-60f7a6b514b6","uId":"4d2b960a-1f3a-47d1-bbc8-7a1b716d193b","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"CAS","domain":"Craft and Structure","skill_cd":"TSP","skill_desc":"Text Structure and Purpose","difficulty":"E","score_band_range_cd":3,"type":"mcq","stimulus":"<p>Composer Florence Price won first place for her score Symphony in E Minor at the 1932 Wanamaker Foundation Awards. The piece was performed the following year by the Chicago Symphony Orchestra, a significant recognition of its quality. Price continued to compose many musical pieces throughout her career, blending traditional Black spirituals with classical European Romantic musical traditions. In recent years, Price&rsquo;s concertos and symphonies have been performed and recorded by several major orchestras, further preserving her work for others to enjoy.</p>","stem":"<p>Which choice best states the main purpose of the text?</p>","answerOptions":[{"id":"3602e1b6-9da4-4d45-a2a8-ccaf1ef4d981","content":"<p>To provide examples of Price&rsquo;s importance as a composer</p>"},{"id":"cde7b78a-6815-4e5a-ab11-506a53463873","content":"<p>To argue that more major orchestras should perform Price&rsquo;s compositions</p>"},{"id":"8456c31c-fa8b-4395-873f-9e7f982f8e73","content":"<p>To describe the musical styles that inspired many of Price&rsquo;s symphonies</p>"},{"id":"c87e1649-a068-4967-b2c4-158078dd8992","content":"<p>To compare Price&rsquo;s scores with those of classical European composers</p>"}],"keys":["3602e1b6-9da4-4d45-a2a8-ccaf1ef4d981"],"correct_answer":["A"],"rationale":"<p>Choice A is the best answer. The text provides an overview of Florence Price&rsquo;s importance by describing her success at the 1932 Wanamaker Foundation Awards, her blending of Black spirituals and classical European Romantic musical traditions, and the recent performances and recordings of her concertos and symphonies by major orchestras. </p><p>Choice B is incorrect. The text does mention that Price&rsquo;s compositions have been performed and recorded by major orchestras, but it doesn&rsquo;t argue that more orchestras should do so. Choice C is incorrect. The text does mention the blending of Black spirituals and classical European Romantic musical traditions, but only briefly, as part of a broader overview of Price&rsquo;s career. Choice D is incorrect. The text mentions Price&rsquo;s blending of Black spirituals with classical European Romantic musical traditions, but it doesn&rsquo;t directly compare Price&rsquo;s scores with those of classical European composers. </p>","parenttemplatename":"OSP-KA-TSP-M006","parenttemplateid":"","templateclusterid":"f04a68b8-2d50-45f9-a2d5-d3098ba44805","templateclustername":"","origin":"proteus","position":"0","createDate":1691007959375,"updateDate":1691007959375}$SATQ$::jsonb, 1691007959375, 1691007959375),
    ($SATQ$ea971260$SATQ$, $SATQ$114e4b2d-8d06-4afa-bc3d-1b27cc0e7446$SATQ$::uuid, $SATQ$2d48de32-0de3-4478-8545-a8537cfecd98$SATQ$::uuid, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Craft and Structure$SATQ$, $SATQ$CAS$SATQ$, $SATQ$TSP$SATQ$, $SATQ$Text Structure and Purpose$SATQ$, $SATQ$E$SATQ$, 3, $SATQ$mcq$SATQ$, $SATQ$<p>The following text is adapted from Louisa May Alcott&rsquo;s 1869 novel <em>An Old-Fashioned Girl</em>. Polly, a teenager, is visiting her friend Fanny.</p>
<blockquote>
<p>Fanny&rsquo;s friends did not interest Polly much; she was rather afraid of them [because] they seemed so much older and wiser than herself, even those younger in years. They talked about things of which she knew nothing and when Fanny tried to explain, she didn&rsquo;t find them interesting; indeed, some of them rather shocked and puzzled her.</p>
</blockquote>$SATQ$, $SATQ$<p>Which choice best states the main purpose of the text?</p>$SATQ$, $SATQ$[{"id":"1f3495b4-2ab6-4245-9ab6-26fcdc7f38e1","content":"<p>To portray Polly&rsquo;s reaction to Fanny&rsquo;s friends</p>"},{"id":"9120a02a-4bcb-4a3d-83e7-d453b8e9d53b","content":"<p>To identify the topics Polly talks about with Fanny&rsquo;s friends</p>"},{"id":"27ef4022-c9dd-496e-8650-68e340f89981","content":"<p>To explain how Fanny met some of her friends</p>"},{"id":"fc4bfc93-088f-4272-a939-4a9a5f30153c","content":"<p>To illustrate how Fanny&rsquo;s friends feel about Polly</p>"}]$SATQ$::jsonb, $SATQ$["A"]$SATQ$::jsonb, $SATQ$["1f3495b4-2ab6-4245-9ab6-26fcdc7f38e1"]$SATQ$::jsonb, $SATQ$<p>Choice A is the best answer because it most accurately describes the main purpose of the text, which is to show how Polly reacted to some of Fanny&rsquo;s other friends. The text describes Polly as being frightened of Fanny&rsquo;s friends because they seemed &ldquo;much older and wiser&rdquo; to her and elaborates that they &ldquo;talked about things of which&rdquo; Polly was unfamiliar, uninterested, and shocked. Thus, the main purpose of the text is to describe Polly&rsquo;s impressions of Fanny&rsquo;s other friends.&nbsp;</p><p>Choice B is incorrect because the text does not provide any of the topics Polly discussed with Fanny&rsquo;s friends, stating only that Polly found the topics unfamiliar, uninteresting, and shocking. Choice C is incorrect because the text says nothing about how Fanny and her other friends first met.&nbsp;Choice D is incorrect because the focus of the text is on Polly&rsquo;s feelings about Fanny&rsquo;s other friends, not on the other friends&rsquo; feelings about Polly. </p>$SATQ$, false, 0, $SATQ$OSP-042-TSP$SATQ$, $SATQ$$SATQ$, $SATQ$31472775-93c3-4fcc-ae97-892f0d38409c$SATQ$::uuid, $SATQ$$SATQ$, $SATQ$proteus$SATQ$, $SATQ$0$SATQ$, NULL, NULL, $SATQ${"questionId":"ea971260","external_id":"114e4b2d-8d06-4afa-bc3d-1b27cc0e7446","vaultid":"2d48de32-0de3-4478-8545-a8537cfecd98","uId":"69ec77e4-c7d7-4efe-9a81-1ce5e38048f9","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"CAS","domain":"Craft and Structure","skill_cd":"TSP","skill_desc":"Text Structure and Purpose","difficulty":"E","score_band_range_cd":3,"type":"mcq","stimulus":"<p>The following text is adapted from Louisa May Alcott&rsquo;s 1869 novel <em>An Old-Fashioned Girl</em>. Polly, a teenager, is visiting her friend Fanny.</p>\n<blockquote>\n<p>Fanny&rsquo;s friends did not interest Polly much; she was rather afraid of them [because] they seemed so much older and wiser than herself, even those younger in years. They talked about things of which she knew nothing and when Fanny tried to explain, she didn&rsquo;t find them interesting; indeed, some of them rather shocked and puzzled her.</p>\n</blockquote>","stem":"<p>Which choice best states the main purpose of the text?</p>","answerOptions":[{"id":"1f3495b4-2ab6-4245-9ab6-26fcdc7f38e1","content":"<p>To portray Polly&rsquo;s reaction to Fanny&rsquo;s friends</p>"},{"id":"9120a02a-4bcb-4a3d-83e7-d453b8e9d53b","content":"<p>To identify the topics Polly talks about with Fanny&rsquo;s friends</p>"},{"id":"27ef4022-c9dd-496e-8650-68e340f89981","content":"<p>To explain how Fanny met some of her friends</p>"},{"id":"fc4bfc93-088f-4272-a939-4a9a5f30153c","content":"<p>To illustrate how Fanny&rsquo;s friends feel about Polly</p>"}],"keys":["1f3495b4-2ab6-4245-9ab6-26fcdc7f38e1"],"correct_answer":["A"],"rationale":"<p>Choice A is the best answer because it most accurately describes the main purpose of the text, which is to show how Polly reacted to some of Fanny&rsquo;s other friends. The text describes Polly as being frightened of Fanny&rsquo;s friends because they seemed &ldquo;much older and wiser&rdquo; to her and elaborates that they &ldquo;talked about things of which&rdquo; Polly was unfamiliar, uninterested, and shocked. Thus, the main purpose of the text is to describe Polly&rsquo;s impressions of Fanny&rsquo;s other friends.&nbsp;</p><p>Choice B is incorrect because the text does not provide any of the topics Polly discussed with Fanny&rsquo;s friends, stating only that Polly found the topics unfamiliar, uninteresting, and shocking. Choice C is incorrect because the text says nothing about how Fanny and her other friends first met.&nbsp;Choice D is incorrect because the focus of the text is on Polly&rsquo;s feelings about Fanny&rsquo;s other friends, not on the other friends&rsquo; feelings about Polly. </p>","parenttemplatename":"OSP-042-TSP","parenttemplateid":"","templateclusterid":"31472775-93c3-4fcc-ae97-892f0d38409c","templateclustername":"","origin":"proteus","position":"0","createDate":1691007959322,"updateDate":1691007959322}$SATQ$::jsonb, 1691007959322, 1691007959322),
    ($SATQ$ea9dfe27$SATQ$, $SATQ$dd21159d-d3f8-45e2-aae9-c408f3e221b7$SATQ$::uuid, NULL, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Craft and Structure$SATQ$, $SATQ$CAS$SATQ$, $SATQ$TSP$SATQ$, $SATQ$Text Structure and Purpose$SATQ$, $SATQ$E$SATQ$, 2, $SATQ$mcq$SATQ$, $SATQ$<p>The following text is from Joan Didion&rsquo;s memoir <em>The Year of Magical Thinking</em>. In the text, the author discusses her home life.</p>
<blockquote>
<p><span data-ssml-sub-alias="In">[I]n</span> California we heated our houses by building fires. We built fires even on summer evenings, because the fog came in. <span style="text-decoration: underline;" role="region" aria-label="Referenced Content">Fires said we were home, we had drawn the circle, we were safe through the night.</span></p>
</blockquote>
<p style="text-align: right;"><span class="dap_copyright">&copy;2005 by Joan Didion</span></p>$SATQ$, $SATQ$<p>Which choice best describes the function of the underlined portion in the text as a whole?</p>$SATQ$, $SATQ$[{"id":"b8eee19e-27d4-4b44-9e16-561e8b632aee","content":"<p>It illustrates that a fire provides comfort beyond physical warmth.</p>"},{"id":"181cbcac-186f-4290-9ae4-49b765b10d4c","content":"<p>It summarizes the information that came before it in the text.</p>"},{"id":"f3107bd8-986e-4983-bd5e-eb854ef0038d","content":"<p>It explains that the house remains cold even in summer.</p>"},{"id":"db7d1552-621a-4f3b-b327-7af0e79019ef","content":"<p>It suggests that the author feels comfortable in her home with or without a fire.</p>"}]$SATQ$::jsonb, $SATQ$["A"]$SATQ$::jsonb, $SATQ$["b8eee19e-27d4-4b44-9e16-561e8b632aee"]$SATQ$::jsonb, $SATQ$<p>Choice A is the best answer because it most accurately describes how the underlined portion functions in the text as a whole. The first two sentences of the text establish that in California, houses were heated by building fires year-round. The underlined portion then indicates that the fires didn&rsquo;t merely provide physical warmth: they also represented being "home" and feeling protected. The underlined portion thus illustrates that a fire provides comfort beyond physical warmth.</p><p>Choice B is incorrect because the underlined portion doesn&rsquo;t summarize information that came before it. Whereas the previous two sentences describe fires&rsquo; ability to provide physical warmth to homes, the underlined portion focuses on the psychological comfort the fires offered. Choice C is incorrect. Although the text&rsquo;s second sentence mentions that fires were built in the summer because fog came in, which may have cooled the house, this detail isn&rsquo;t the focus of the underlined portion. Instead, the underlined portion indicates that fires were built for reasons beyond physical warmth: to create a sense of being home and safe. Choice D is incorrect because the underlined portion focuses on the emotional significance the author places on having a fire going inside the home. There is no indication that the author feels equally comfortable without a fire present.</p>$SATQ$, false, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, $SATQ${"questionId":"ea9dfe27","external_id":"dd21159d-d3f8-45e2-aae9-c408f3e221b7","vaultid":null,"uId":"71564701-b50a-43c8-8810-64202df68434","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"CAS","domain":"Craft and Structure","skill_cd":"TSP","skill_desc":"Text Structure and Purpose","difficulty":"E","score_band_range_cd":2,"type":"mcq","stimulus":"<p>The following text is from Joan Didion&rsquo;s memoir <em>The Year of Magical Thinking</em>. In the text, the author discusses her home life.</p>\n<blockquote>\n<p><span data-ssml-sub-alias=\"In\">[I]n</span> California we heated our houses by building fires. We built fires even on summer evenings, because the fog came in. <span style=\"text-decoration: underline;\" role=\"region\" aria-label=\"Referenced Content\">Fires said we were home, we had drawn the circle, we were safe through the night.</span></p>\n</blockquote>\n<p style=\"text-align: right;\"><span class=\"dap_copyright\">&copy;2005 by Joan Didion</span></p>","stem":"<p>Which choice best describes the function of the underlined portion in the text as a whole?</p>","answerOptions":[{"id":"b8eee19e-27d4-4b44-9e16-561e8b632aee","content":"<p>It illustrates that a fire provides comfort beyond physical warmth.</p>"},{"id":"181cbcac-186f-4290-9ae4-49b765b10d4c","content":"<p>It summarizes the information that came before it in the text.</p>"},{"id":"f3107bd8-986e-4983-bd5e-eb854ef0038d","content":"<p>It explains that the house remains cold even in summer.</p>"},{"id":"db7d1552-621a-4f3b-b327-7af0e79019ef","content":"<p>It suggests that the author feels comfortable in her home with or without a fire.</p>"}],"keys":["b8eee19e-27d4-4b44-9e16-561e8b632aee"],"correct_answer":["A"],"rationale":"<p>Choice A is the best answer because it most accurately describes how the underlined portion functions in the text as a whole. The first two sentences of the text establish that in California, houses were heated by building fires year-round. The underlined portion then indicates that the fires didn&rsquo;t merely provide physical warmth: they also represented being \"home\" and feeling protected. The underlined portion thus illustrates that a fire provides comfort beyond physical warmth.</p><p>Choice B is incorrect because the underlined portion doesn&rsquo;t summarize information that came before it. Whereas the previous two sentences describe fires&rsquo; ability to provide physical warmth to homes, the underlined portion focuses on the psychological comfort the fires offered. Choice C is incorrect. Although the text&rsquo;s second sentence mentions that fires were built in the summer because fog came in, which may have cooled the house, this detail isn&rsquo;t the focus of the underlined portion. Instead, the underlined portion indicates that fires were built for reasons beyond physical warmth: to create a sense of being home and safe. Choice D is incorrect because the underlined portion focuses on the emotional significance the author places on having a fire going inside the home. There is no indication that the author feels equally comfortable without a fire present.</p>","parenttemplatename":null,"parenttemplateid":null,"templateclusterid":null,"templateclustername":null,"origin":null,"position":null,"createDate":1743430669213,"updateDate":1743430669213}$SATQ$::jsonb, 1743430669213, 1743430669213),
    ($SATQ$eae66bf9$SATQ$, $SATQ$06b4befe-cc57-404a-b9d6-dea9e85fdec6$SATQ$::uuid, $SATQ$b4733790-ed94-4bdf-b509-a53e7b00b5f2$SATQ$::uuid, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Craft and Structure$SATQ$, $SATQ$CAS$SATQ$, $SATQ$CTC$SATQ$, $SATQ$Cross-Text Connections$SATQ$, $SATQ$M$SATQ$, 5, $SATQ$mcq$SATQ$, $SATQ$<p><strong><span role="heading" aria-level="2">Text 1</span></strong></p>
<p>In 2021, a team led by Amir Siraj hypothesized that the Chicxulub impactor&mdash;the object that struck the Yucat&aacute;n Peninsula sixty-six million years ago, precipitating the mass extinction of the dinosaurs&mdash;was likely a member of the class of long-period comets. As evidence, Siraj cited the carbonaceous chondritic composition of samples from the Chicxulub impact crater as well as of samples obtained from long-period comet Wild 2 in 2006.</p>
<p>&nbsp;</p>
<p><strong><span role="heading" aria-level="2">Text 2</span></strong></p>
<p>Although long-period comets contain carbonaceous chondrites, asteroids are similarly rich in these materials. Furthermore, some asteroids are rich in iridium, as Natalia Artemieva points out, whereas long-period comets are not. Given the prevalence of iridium at the crater and, more broadly, in geological layers deposited worldwide following the impact, Artemieva argues that an asteroid is a more plausible candidate for the Chicxulub impactor.</p>$SATQ$, $SATQ$<p>Based on the texts, how would Artemieva likely respond to Siraj&rsquo;s hypothesis, as presented in Text 1?</p>$SATQ$, $SATQ$[{"id":"a4bb901a-336b-42cf-9d45-d50ab89f69a6","content":"<p>By insisting that it overestimates how representative Wild 2 is of long-period comets as a class</p>"},{"id":"d31dad27-4927-43e1-b786-2544ff3c0123","content":"<p>By arguing that it does not account for the amount of iridium found in geological layers dating to the Chicxulub impact</p>"},{"id":"3a1a838b-5780-40a1-ac08-1dc528320660","content":"<p>By praising it for connecting the composition of Chicxulub crater samples to the composition of certain asteroids</p>"},{"id":"3b95452e-4ae8-4c5d-bf6a-4fc7416bf236","content":"<p>By concurring that carbonaceous chondrites are prevalent in soil samples from sites distant from the Chicxulub crater</p>"}]$SATQ$::jsonb, $SATQ$["B"]$SATQ$::jsonb, $SATQ$["d31dad27-4927-43e1-b786-2544ff3c0123"]$SATQ$::jsonb, $SATQ$<p>Choice B is the best answer. Siraj&rsquo;s hypothesis is that the Chicxulub impactor was a long-period comet. But Artemieva points to the iridium found in the crater and in &ldquo;geological layers that were deposited worldwide after the impact&rdquo; as evidence that it was actually an asteroid, not a long-period comet. </p><p>Choice A is incorrect. We can&rsquo;t infer that this is how Artemieva would respond to Siraj&rsquo;s hypothesis. Text 2 never discusses whether Wild 2 is representative of long-period comets in general. Rather, Text 2 presents Artemieva&rsquo;s argument that the Chicxulub impactor was an asteroid, not a long-term comet. Choice C is incorrect. We can&rsquo;t infer that this is how Artemieva would respond to Siraj&rsquo;s hypothesis. Siraj&rsquo;s hypothesis doesn&rsquo;t make this connection: rather, Siraj hypothesizes that the Chicxulub impactor was a long-term comet. Choice D is incorrect. We can&rsquo;t infer that this is how Artemieva would respond to Siraj&rsquo;s hypothesis. &ldquo;Soil samples from sites distant from the Chicxulub crater&rdquo; is too vague. Only soil samples from sites that are connected to the impact in some way are involved in either hypothesis. </p>$SATQ$, false, 0, $SATQ$OSP-KA-CTC-M004$SATQ$, $SATQ$$SATQ$, $SATQ$ad9b1367-372d-41ba-a775-1a13f0aa07da$SATQ$::uuid, $SATQ$$SATQ$, $SATQ$proteus$SATQ$, $SATQ$0$SATQ$, NULL, NULL, $SATQ${"questionId":"eae66bf9","external_id":"06b4befe-cc57-404a-b9d6-dea9e85fdec6","vaultid":"b4733790-ed94-4bdf-b509-a53e7b00b5f2","uId":"95996361-6140-4f02-bcbd-148983cbb331","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"CAS","domain":"Craft and Structure","skill_cd":"CTC","skill_desc":"Cross-Text Connections","difficulty":"M","score_band_range_cd":5,"type":"mcq","stimulus":"<p><strong><span role=\"heading\" aria-level=\"2\">Text 1</span></strong></p>\n<p>In 2021, a team led by Amir Siraj hypothesized that the Chicxulub impactor&mdash;the object that struck the Yucat&aacute;n Peninsula sixty-six million years ago, precipitating the mass extinction of the dinosaurs&mdash;was likely a member of the class of long-period comets. As evidence, Siraj cited the carbonaceous chondritic composition of samples from the Chicxulub impact crater as well as of samples obtained from long-period comet Wild 2 in 2006.</p>\n<p>&nbsp;</p>\n<p><strong><span role=\"heading\" aria-level=\"2\">Text 2</span></strong></p>\n<p>Although long-period comets contain carbonaceous chondrites, asteroids are similarly rich in these materials. Furthermore, some asteroids are rich in iridium, as Natalia Artemieva points out, whereas long-period comets are not. Given the prevalence of iridium at the crater and, more broadly, in geological layers deposited worldwide following the impact, Artemieva argues that an asteroid is a more plausible candidate for the Chicxulub impactor.</p>","stem":"<p>Based on the texts, how would Artemieva likely respond to Siraj&rsquo;s hypothesis, as presented in Text 1?</p>","answerOptions":[{"id":"a4bb901a-336b-42cf-9d45-d50ab89f69a6","content":"<p>By insisting that it overestimates how representative Wild 2 is of long-period comets as a class</p>"},{"id":"d31dad27-4927-43e1-b786-2544ff3c0123","content":"<p>By arguing that it does not account for the amount of iridium found in geological layers dating to the Chicxulub impact</p>"},{"id":"3a1a838b-5780-40a1-ac08-1dc528320660","content":"<p>By praising it for connecting the composition of Chicxulub crater samples to the composition of certain asteroids</p>"},{"id":"3b95452e-4ae8-4c5d-bf6a-4fc7416bf236","content":"<p>By concurring that carbonaceous chondrites are prevalent in soil samples from sites distant from the Chicxulub crater</p>"}],"keys":["d31dad27-4927-43e1-b786-2544ff3c0123"],"correct_answer":["B"],"rationale":"<p>Choice B is the best answer. Siraj&rsquo;s hypothesis is that the Chicxulub impactor was a long-period comet. But Artemieva points to the iridium found in the crater and in &ldquo;geological layers that were deposited worldwide after the impact&rdquo; as evidence that it was actually an asteroid, not a long-period comet. </p><p>Choice A is incorrect. We can&rsquo;t infer that this is how Artemieva would respond to Siraj&rsquo;s hypothesis. Text 2 never discusses whether Wild 2 is representative of long-period comets in general. Rather, Text 2 presents Artemieva&rsquo;s argument that the Chicxulub impactor was an asteroid, not a long-term comet. Choice C is incorrect. We can&rsquo;t infer that this is how Artemieva would respond to Siraj&rsquo;s hypothesis. Siraj&rsquo;s hypothesis doesn&rsquo;t make this connection: rather, Siraj hypothesizes that the Chicxulub impactor was a long-term comet. Choice D is incorrect. We can&rsquo;t infer that this is how Artemieva would respond to Siraj&rsquo;s hypothesis. &ldquo;Soil samples from sites distant from the Chicxulub crater&rdquo; is too vague. Only soil samples from sites that are connected to the impact in some way are involved in either hypothesis. </p>","parenttemplatename":"OSP-KA-CTC-M004","parenttemplateid":"","templateclusterid":"ad9b1367-372d-41ba-a775-1a13f0aa07da","templateclustername":"","origin":"proteus","position":"0","createDate":1691007959366,"updateDate":1691007959366}$SATQ$::jsonb, 1691007959366, 1691007959366),
    ($SATQ$eaea6f8f$SATQ$, $SATQ$d731ebc9-44c8-4a29-9258-39c857313259$SATQ$::uuid, NULL, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Craft and Structure$SATQ$, $SATQ$CAS$SATQ$, $SATQ$TSP$SATQ$, $SATQ$Text Structure and Purpose$SATQ$, $SATQ$E$SATQ$, 3, $SATQ$mcq$SATQ$, $SATQ$<p>Ordinary soap bubbles usually exist for a minute or less before popping due to either a rupture forced by gravity-induced drainage or the evaporation of the liquid from which the bubble is composed. But physicist Aymeric Roux and colleagues discovered ways to mitigate these factors, resulting in bubbles that can last for a year or more. For example, glycerol tends to adhere to water molecules, so <span role="region" aria-label="Referenced Content"><u>a bubble with a shell that contains both water and glycerol is able to draw additional water molecules from the surrounding air and thereby compensate for evaporation.</u></span></p>$SATQ$, $SATQ$<p>Which choice best states the purpose of the underlined portion in the text as a whole?</p>$SATQ$, $SATQ$[{"id":"e419aec8-ed09-4e53-aac5-9b7794137611","content":"<p>It describes the effects of a process devised by researchers that increases the longevity of an object discussed in the text.</p>"},{"id":"d7cf8045-f30a-428a-940d-3d3dd4353c27","content":"<p>It details the circumstances that prompted the research discussed in the text.</p>"},{"id":"1c0d4487-2f77-4e4b-a9fb-aad4308a192a","content":"<p>It presents a reason why the phenomenon discussed in the text that the researchers wanted to avoid will inevitably occur.</p>"},{"id":"6a865a07-4eda-4256-86fc-9f583008b241","content":"<p>It mentions a method discussed in the text that researchers intend to test in future experiments.</p>"}]$SATQ$::jsonb, $SATQ$["A"]$SATQ$::jsonb, $SATQ$["e419aec8-ed09-4e53-aac5-9b7794137611"]$SATQ$::jsonb, $SATQ$<p>Choice A is the best answer because it describes how the underlined portion of the sentence functions in the text as a whole. The text begins by discussing ordinary soap bubbles, objects that usually exist for less than a minute before popping due to either evaporation or gravity-induced drainage. The text then goes on to mention work by researchers Aymeric Roux and colleagues, who have discovered how to increase the longevity of bubbles by altering their chemical composition. Finally, the underlined portion of the text describes how this process works: since the bubble contains both water and glycerol, it can draw water molecules from the surrounding air to replace those lost to evaporation. Therefore, the underlined portion of the sentence describes the effects of a process devised by researchers that increases the longevity of an object described in the text.</p><p>Choice B is incorrect because the circumstance that prompted the research is discussed in the first sentence of the text, not the underlined portion. Choice C is incorrect because the underlined portion of the text does not address why soap bubbles must eventually rupture. Rather, it explains how the longevity of soap bubbles can be extended. Choice D is incorrect because the underlined portion of the text does not mention any future experiments.</p>$SATQ$, false, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, $SATQ${"questionId":"eaea6f8f","external_id":"d731ebc9-44c8-4a29-9258-39c857313259","vaultid":null,"uId":"191cd5fb-1cf9-4faa-9d3b-975330cb2f5e","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"CAS","domain":"Craft and Structure","skill_cd":"TSP","skill_desc":"Text Structure and Purpose","difficulty":"E","score_band_range_cd":3,"type":"mcq","stimulus":"<p>Ordinary soap bubbles usually exist for a minute or less before popping due to either a rupture forced by gravity-induced drainage or the evaporation of the liquid from which the bubble is composed. But physicist Aymeric Roux and colleagues discovered ways to mitigate these factors, resulting in bubbles that can last for a year or more. For example, glycerol tends to adhere to water molecules, so <span role=\"region\" aria-label=\"Referenced Content\"><u>a bubble with a shell that contains both water and glycerol is able to draw additional water molecules from the surrounding air and thereby compensate for evaporation.</u></span></p>","stem":"<p>Which choice best states the purpose of the underlined portion in the text as a whole?</p>","answerOptions":[{"id":"e419aec8-ed09-4e53-aac5-9b7794137611","content":"<p>It describes the effects of a process devised by researchers that increases the longevity of an object discussed in the text.</p>"},{"id":"d7cf8045-f30a-428a-940d-3d3dd4353c27","content":"<p>It details the circumstances that prompted the research discussed in the text.</p>"},{"id":"1c0d4487-2f77-4e4b-a9fb-aad4308a192a","content":"<p>It presents a reason why the phenomenon discussed in the text that the researchers wanted to avoid will inevitably occur.</p>"},{"id":"6a865a07-4eda-4256-86fc-9f583008b241","content":"<p>It mentions a method discussed in the text that researchers intend to test in future experiments.</p>"}],"keys":["e419aec8-ed09-4e53-aac5-9b7794137611"],"correct_answer":["A"],"rationale":"<p>Choice A is the best answer because it describes how the underlined portion of the sentence functions in the text as a whole. The text begins by discussing ordinary soap bubbles, objects that usually exist for less than a minute before popping due to either evaporation or gravity-induced drainage. The text then goes on to mention work by researchers Aymeric Roux and colleagues, who have discovered how to increase the longevity of bubbles by altering their chemical composition. Finally, the underlined portion of the text describes how this process works: since the bubble contains both water and glycerol, it can draw water molecules from the surrounding air to replace those lost to evaporation. Therefore, the underlined portion of the sentence describes the effects of a process devised by researchers that increases the longevity of an object described in the text.</p><p>Choice B is incorrect because the circumstance that prompted the research is discussed in the first sentence of the text, not the underlined portion. Choice C is incorrect because the underlined portion of the text does not address why soap bubbles must eventually rupture. Rather, it explains how the longevity of soap bubbles can be extended. Choice D is incorrect because the underlined portion of the text does not mention any future experiments.</p>","parenttemplatename":null,"parenttemplateid":null,"templateclusterid":null,"templateclustername":null,"origin":null,"position":null,"createDate":1730147323034,"updateDate":1730147323034}$SATQ$::jsonb, 1730147323034, 1730147323034),
    ($SATQ$eb89dcc8$SATQ$, $SATQ$6a4d62ba-60da-4cae-a4a8-3e352892c144$SATQ$::uuid, NULL, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Craft and Structure$SATQ$, $SATQ$CAS$SATQ$, $SATQ$CTC$SATQ$, $SATQ$Cross-Text Connections$SATQ$, $SATQ$E$SATQ$, 3, $SATQ$mcq$SATQ$, $SATQ$<p><span class="paired_passage" role="heading" aria-level="2"><strong>Text 1</strong></span></p>
<p><span style="text-decoration: underline;" role="region" aria-label="Referenced Content">Imagine you and your friend are trying to decide where to eat lunch.</span> When people try to make joint decisions like this, they often don&rsquo;t reveal their true preferences. Instead, they say they would be happy with all options because they think this response will help them appear more easygoing and likable to the other person.</p>
<p>&nbsp;</p>
<p><span class="paired_passage" role="heading" aria-level="2"><strong>Text 2</strong></span></p>
<p>Research shows that people who don&rsquo;t state their preferences when making a decision with others aren&rsquo;t more likable in the eyes of others. In fact, stating that you have no preference actually makes the decision more difficult for other people. It can also cause them to feel less happy with their ultimate decision and with you.</p>$SATQ$, $SATQ$<p>Based on the texts, what response would the author of Text 2 most likely suggest for someone in the situation described in the underlined sentence in Text 1?</p>$SATQ$, $SATQ$[{"id":"d71dc52c-7633-4854-84d4-98f8f25fccfe","content":"<p>Cancel the plan to have lunch together.</p>"},{"id":"a0f08fb5-294f-438c-b7aa-37f54db1abb3","content":"<p>Ask where the friend typically likes to eat.</p>"},{"id":"f7caee94-2049-4e66-bc24-e67841c3e483","content":"<p>State a preference about where to eat.</p>"},{"id":"a8fc6770-dee9-401a-a36b-03531dacf7c7","content":"<p>Change the subject to talk about something else.</p>"}]$SATQ$::jsonb, $SATQ$["C"]$SATQ$::jsonb, $SATQ$["f7caee94-2049-4e66-bc24-e67841c3e483"]$SATQ$::jsonb, $SATQ$<p>Choice C is the best answer because it directly applies the research findings described in Text 2 to the situation underlined in Text 1. The underlined sentence in Text 1 describes a common scenario in which two friends are deciding on a lunch location. Text 1 goes on to explain that people often don&rsquo;t reveal their true preferences in such situations, instead claiming they&rsquo;re fine with any option so that they can appear more easygoing and likable. Text 2 presents research that advises against this approach, stating that people who don&rsquo;t express their preferences aren&rsquo;t viewed as more likable and that this behavior actually makes decisions more difficult for others. Since Text 2 specifically argues against the strategy of concealing preferences and indicates negative outcomes from doing so, the author of Text 2 would most likely recommend stating a preference about where to eat.</p><p>Choice A is incorrect because nothing in Text 2 suggests that canceling plans is a good solution. The author of Text 2 is addressing how to make joint decisions effectively (through stating your own preference), not advocating for avoiding such decisions entirely. Choice B is incorrect because asking where the friend typically likes to eat still avoids stating one&rsquo;s own preference. While this approach might seem considerate, it continues the pattern of not revealing true preferences that Text 2 identifies as problematic. Choice D is incorrect because changing the subject would avoid making any decision altogether, which contradicts the implied advice in Text 2. The author of Text 2 presents research suggesting that directly engaging with the decision by stating preferences helps others make decisions and makes you appear more likable.</p>$SATQ$, false, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, $SATQ${"questionId":"eb89dcc8","external_id":"6a4d62ba-60da-4cae-a4a8-3e352892c144","vaultid":null,"uId":"09274645-1a9a-4e34-8463-9ecb3a47c5f1","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"CAS","domain":"Craft and Structure","skill_cd":"CTC","skill_desc":"Cross-Text Connections","difficulty":"E","score_band_range_cd":3,"type":"mcq","stimulus":"<p><span class=\"paired_passage\" role=\"heading\" aria-level=\"2\"><strong>Text 1</strong></span></p>\n<p><span style=\"text-decoration: underline;\" role=\"region\" aria-label=\"Referenced Content\">Imagine you and your friend are trying to decide where to eat lunch.</span> When people try to make joint decisions like this, they often don&rsquo;t reveal their true preferences. Instead, they say they would be happy with all options because they think this response will help them appear more easygoing and likable to the other person.</p>\n<p>&nbsp;</p>\n<p><span class=\"paired_passage\" role=\"heading\" aria-level=\"2\"><strong>Text 2</strong></span></p>\n<p>Research shows that people who don&rsquo;t state their preferences when making a decision with others aren&rsquo;t more likable in the eyes of others. In fact, stating that you have no preference actually makes the decision more difficult for other people. It can also cause them to feel less happy with their ultimate decision and with you.</p>","stem":"<p>Based on the texts, what response would the author of Text 2 most likely suggest for someone in the situation described in the underlined sentence in Text 1?</p>","answerOptions":[{"id":"d71dc52c-7633-4854-84d4-98f8f25fccfe","content":"<p>Cancel the plan to have lunch together.</p>"},{"id":"a0f08fb5-294f-438c-b7aa-37f54db1abb3","content":"<p>Ask where the friend typically likes to eat.</p>"},{"id":"f7caee94-2049-4e66-bc24-e67841c3e483","content":"<p>State a preference about where to eat.</p>"},{"id":"a8fc6770-dee9-401a-a36b-03531dacf7c7","content":"<p>Change the subject to talk about something else.</p>"}],"keys":["f7caee94-2049-4e66-bc24-e67841c3e483"],"correct_answer":["C"],"rationale":"<p>Choice C is the best answer because it directly applies the research findings described in Text 2 to the situation underlined in Text 1. The underlined sentence in Text 1 describes a common scenario in which two friends are deciding on a lunch location. Text 1 goes on to explain that people often don&rsquo;t reveal their true preferences in such situations, instead claiming they&rsquo;re fine with any option so that they can appear more easygoing and likable. Text 2 presents research that advises against this approach, stating that people who don&rsquo;t express their preferences aren&rsquo;t viewed as more likable and that this behavior actually makes decisions more difficult for others. Since Text 2 specifically argues against the strategy of concealing preferences and indicates negative outcomes from doing so, the author of Text 2 would most likely recommend stating a preference about where to eat.</p><p>Choice A is incorrect because nothing in Text 2 suggests that canceling plans is a good solution. The author of Text 2 is addressing how to make joint decisions effectively (through stating your own preference), not advocating for avoiding such decisions entirely. Choice B is incorrect because asking where the friend typically likes to eat still avoids stating one&rsquo;s own preference. While this approach might seem considerate, it continues the pattern of not revealing true preferences that Text 2 identifies as problematic. Choice D is incorrect because changing the subject would avoid making any decision altogether, which contradicts the implied advice in Text 2. The author of Text 2 presents research suggesting that directly engaging with the decision by stating preferences helps others make decisions and makes you appear more likable.</p>","parenttemplatename":null,"parenttemplateid":null,"templateclusterid":null,"templateclustername":null,"origin":null,"position":null,"createDate":1755117061178,"updateDate":1755117061178}$SATQ$::jsonb, 1755117061178, 1755117061178),
    ($SATQ$ed52a093$SATQ$, $SATQ$528036fb-b773-45a9-a0e1-9d0a9ac30ee2$SATQ$::uuid, NULL, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Craft and Structure$SATQ$, $SATQ$CAS$SATQ$, $SATQ$CTC$SATQ$, $SATQ$Cross-Text Connections$SATQ$, $SATQ$E$SATQ$, 3, $SATQ$mcq$SATQ$, $SATQ$<p><span class="paired_passage" role="heading" aria-level="2"><strong>Text 1</strong></span></p>
<p>Flamingos are known for their vibrant pink coloring, but they&rsquo;re actually born with gray feathers. Their pink color comes from eating brine shrimp, but brine shrimp aren&rsquo;t naturally pink either. Animals can&rsquo;t produce carotenoids, the pigments that provide the pink hue. The algae that brine shrimp feed on, however, can produce these pigments. Thus, the pinker the flamingo, the more shrimp it has eaten.</p>
<p>&nbsp;</p>
<p><span class="paired_passage" role="heading" aria-level="2"><strong>Text 2</strong></span></p>
<p>Ecologist Juan Amat has found that flamingos apply a kind of makeup to make themselves appear pinker. A gland near their tail contains pigments that come from the food they eat. When the flamingos groom themselves using the pigments, their feathers become pinker. Flamingos may do this to improve their success during mating season, when they would benefit from looking pinker.</p>$SATQ$, $SATQ$<p>Based on the texts, how would the ecologist in Text 2 most likely respond to the author&rsquo;s conclusion in Text 1?</p>$SATQ$, $SATQ$[{"id":"4ea52f0f-a85e-47bc-a717-23362c3d06be","content":"<p>By emphasizing that flamingos&rsquo; tail feathers are pinker than their other feathers are</p>"},{"id":"9818b117-ccbc-4bc6-8284-b8dadc70bbf5","content":"<p>By claiming that the coloring of flamingos&rsquo; feathers doesn&rsquo;t change significantly enough for most observers to notice</p>"},{"id":"3bd58c0d-eff9-4c33-8e4a-8d9792c13f62","content":"<p>By pointing out that the amount of shrimp eaten isn&rsquo;t the only thing that influences flamingos&rsquo; coloring</p>"},{"id":"f90ecd59-8105-4779-ab90-a2b891a23349","content":"<p>By arguing that flamingos&rsquo; diet doesn&rsquo;t include much shrimp except during mating season</p>"}]$SATQ$::jsonb, $SATQ$["C"]$SATQ$::jsonb, $SATQ$["3bd58c0d-eff9-4c33-8e4a-8d9792c13f62"]$SATQ$::jsonb, $SATQ$<p>Choice C is the best answer because it describes how the ecologist in Text 2 would most likely respond to the author&rsquo;s conclusion in Text 1 based on the information provided. The author of Text 1 states that the pink color of flamingo feathers comes from pigments carried by the brine shrimp flamingos consume. The author of Text 1 concludes that this means that a flamingo that is pinker than another flamingo must have eaten more shrimp. However, according to Text 2, ecologist Juan Amat has found that flamingos can also affect how pink they look through grooming, when they move ingested pigments from a gland near the tail to their feathers. This indicates that not all the pigments available from the shrimp a flamingo has eaten automatically end up coloring the flamingo&rsquo;s feathers; some may or may not be applied later. Since grooming is also a factor, the ecologist (Amat) in Text 2 would most likely respond to the conclusion in Text 1 that pinker flamingos have eaten more shrimp by pointing out that the amount of shrimp eaten isn&rsquo;t the only thing that influences flamingos&rsquo; coloring.</p><p>Choice A is incorrect. Although Text 2 states that the ecologist has found that flamingos can move pigments to their feathers from a gland near their tail, there is no indication that their tail feathers are pinker than their other feathers. Moreover, the point that tail feathers are pinker than other feathers wouldn&rsquo;t logically address the idea that the quantity of shrimp eaten is what determines a flamingo&rsquo;s coloring. Choice B is incorrect because Text 2 indicates that the ecologist has found that flamingos&rsquo; feathers do sometimes look pinker and gives no indication that this change in color is particularly subtle. Moreover, the point that most observers wouldn&rsquo;t notice a change wouldn&rsquo;t logically address the idea that the quantity of shrimp eaten is what determines a flamingo&rsquo;s coloring. Choice D is incorrect because nothing in Text 2 suggests that the ecologist would argue about flamingos&rsquo; shrimp consumption. Although Text 2 indicates that the ecologist has found that flamingos may make themselves look pinker during mating season, this is addressed in terms of grooming habits; apart from referring to food as a source of pigments, Text 2 doesn&rsquo;t discuss the diet of flamingos at all.</p>$SATQ$, false, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, $SATQ${"questionId":"ed52a093","external_id":"528036fb-b773-45a9-a0e1-9d0a9ac30ee2","vaultid":null,"uId":"4bc66b8a-17eb-493e-8dae-66ac87972fd5","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"CAS","domain":"Craft and Structure","skill_cd":"CTC","skill_desc":"Cross-Text Connections","difficulty":"E","score_band_range_cd":3,"type":"mcq","stimulus":"<p><span class=\"paired_passage\" role=\"heading\" aria-level=\"2\"><strong>Text 1</strong></span></p>\n<p>Flamingos are known for their vibrant pink coloring, but they&rsquo;re actually born with gray feathers. Their pink color comes from eating brine shrimp, but brine shrimp aren&rsquo;t naturally pink either. Animals can&rsquo;t produce carotenoids, the pigments that provide the pink hue. The algae that brine shrimp feed on, however, can produce these pigments. Thus, the pinker the flamingo, the more shrimp it has eaten.</p>\n<p>&nbsp;</p>\n<p><span class=\"paired_passage\" role=\"heading\" aria-level=\"2\"><strong>Text 2</strong></span></p>\n<p>Ecologist Juan Amat has found that flamingos apply a kind of makeup to make themselves appear pinker. A gland near their tail contains pigments that come from the food they eat. When the flamingos groom themselves using the pigments, their feathers become pinker. Flamingos may do this to improve their success during mating season, when they would benefit from looking pinker.</p>","stem":"<p>Based on the texts, how would the ecologist in Text 2 most likely respond to the author&rsquo;s conclusion in Text 1?</p>","answerOptions":[{"id":"4ea52f0f-a85e-47bc-a717-23362c3d06be","content":"<p>By emphasizing that flamingos&rsquo; tail feathers are pinker than their other feathers are</p>"},{"id":"9818b117-ccbc-4bc6-8284-b8dadc70bbf5","content":"<p>By claiming that the coloring of flamingos&rsquo; feathers doesn&rsquo;t change significantly enough for most observers to notice</p>"},{"id":"3bd58c0d-eff9-4c33-8e4a-8d9792c13f62","content":"<p>By pointing out that the amount of shrimp eaten isn&rsquo;t the only thing that influences flamingos&rsquo; coloring</p>"},{"id":"f90ecd59-8105-4779-ab90-a2b891a23349","content":"<p>By arguing that flamingos&rsquo; diet doesn&rsquo;t include much shrimp except during mating season</p>"}],"keys":["3bd58c0d-eff9-4c33-8e4a-8d9792c13f62"],"correct_answer":["C"],"rationale":"<p>Choice C is the best answer because it describes how the ecologist in Text 2 would most likely respond to the author&rsquo;s conclusion in Text 1 based on the information provided. The author of Text 1 states that the pink color of flamingo feathers comes from pigments carried by the brine shrimp flamingos consume. The author of Text 1 concludes that this means that a flamingo that is pinker than another flamingo must have eaten more shrimp. However, according to Text 2, ecologist Juan Amat has found that flamingos can also affect how pink they look through grooming, when they move ingested pigments from a gland near the tail to their feathers. This indicates that not all the pigments available from the shrimp a flamingo has eaten automatically end up coloring the flamingo&rsquo;s feathers; some may or may not be applied later. Since grooming is also a factor, the ecologist (Amat) in Text 2 would most likely respond to the conclusion in Text 1 that pinker flamingos have eaten more shrimp by pointing out that the amount of shrimp eaten isn&rsquo;t the only thing that influences flamingos&rsquo; coloring.</p><p>Choice A is incorrect. Although Text 2 states that the ecologist has found that flamingos can move pigments to their feathers from a gland near their tail, there is no indication that their tail feathers are pinker than their other feathers. Moreover, the point that tail feathers are pinker than other feathers wouldn&rsquo;t logically address the idea that the quantity of shrimp eaten is what determines a flamingo&rsquo;s coloring. Choice B is incorrect because Text 2 indicates that the ecologist has found that flamingos&rsquo; feathers do sometimes look pinker and gives no indication that this change in color is particularly subtle. Moreover, the point that most observers wouldn&rsquo;t notice a change wouldn&rsquo;t logically address the idea that the quantity of shrimp eaten is what determines a flamingo&rsquo;s coloring. Choice D is incorrect because nothing in Text 2 suggests that the ecologist would argue about flamingos&rsquo; shrimp consumption. Although Text 2 indicates that the ecologist has found that flamingos may make themselves look pinker during mating season, this is addressed in terms of grooming habits; apart from referring to food as a source of pigments, Text 2 doesn&rsquo;t discuss the diet of flamingos at all.</p>","parenttemplatename":null,"parenttemplateid":null,"templateclusterid":null,"templateclustername":null,"origin":null,"position":null,"createDate":1730147323032,"updateDate":1730147323032}$SATQ$::jsonb, 1730147323032, 1730147323032),
    ($SATQ$edbc6cca$SATQ$, $SATQ$3a426293-3d0c-4938-8e24-6def7aeb6b41$SATQ$::uuid, NULL, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Craft and Structure$SATQ$, $SATQ$CAS$SATQ$, $SATQ$TSP$SATQ$, $SATQ$Text Structure and Purpose$SATQ$, $SATQ$E$SATQ$, 3, $SATQ$mcq$SATQ$, $SATQ$<p>The following text is from Bram Stoker&rsquo;s 1911 novel <em>The Lair of the White Worm</em>. Adam is meeting his great-uncle Richard at a port.</p>
<blockquote>
<p>The meeting so auspiciously begun proceeded well. Adam, seeing that the old man was interested in the novelty of the ship, suggested that he should stay the night on board, and that he would himself be ready to start at any hour and go anywhere that the other suggested. This affectionate willingness to fall in with his own plans quite won the old man&rsquo;s heart. He warmly accepted the invitation, and at once they became not only on terms of affectionate relationship, but almost like old friends.</p>
</blockquote>$SATQ$, $SATQ$<p>Which choice best states the main purpose of the text?</p>$SATQ$, $SATQ$[{"id":"586588de-d5c0-4bde-9a7a-b67704fda2ab","content":"<p>It states the reasons why Adam and his great-uncle Richard decide to sleep on the ship rather than finding lodging on land.</p>"},{"id":"f38e81d1-1c66-492e-ab09-799c9c8ea411","content":"<p>It showcases how Adam&rsquo;s flexibility and consideration strengthen his relationship with his great-uncle Richard.</p>"},{"id":"1f95fc68-4478-4963-a308-3c46a6f3f551","content":"<p>It describes why Adam and his great-uncle Richard are excited for their upcoming journey on the ship.&nbsp;</p>"},{"id":"0eb2903c-db1d-48ac-91b1-e88369e54df8","content":"<p>It contrasts great-uncle Richard&rsquo;s wary first impressions of Adam with his ultimate affection toward him.</p>"}]$SATQ$::jsonb, $SATQ$["B"]$SATQ$::jsonb, $SATQ$["f38e81d1-1c66-492e-ab09-799c9c8ea411"]$SATQ$::jsonb, $SATQ$<p>Choice B is the best answer because it most accurately describes the main purpose of the text, which is to showcase how Adam&rsquo;s flexibility and consideration strengthen his relationship with his great-uncle Richard. The text begins by stating that the meeting between the two characters is proceeding well and then describes Adam&rsquo;s thoughtful behavior: noticing his great-uncle&rsquo;s interest in the ship, Adam suggests staying on board overnight and expresses willingness to accommodate his great-uncle&rsquo;s schedule and destination preferences. The text goes on to describe the positive effect of Adam&rsquo;s thoughtfulness and flexibility, indicating that Adam&rsquo;s &ldquo;affectionate willingness&rdquo; to accommodate Richard&rsquo;s preferences &ldquo;quite won the old man&rsquo;s heart.&rdquo; The text concludes by suggesting that Adam&rsquo;s ability to anticipate his great-uncle&rsquo;s wishes and willingness to accommodate them result in the rapid development of affection and intimacy between them, stating that they soon became &ldquo;almost like old friends.&rdquo; Therefore, the text&rsquo;s main purpose is to demonstrate how Adam&rsquo;s flexibility and consideration strengthened his and his great-uncle&rsquo;s relationship.</p><p>Choice A is incorrect. Although the text explains Adam&rsquo;s reason for suggesting that Richard spend the night on the ship rather than finding lodging on land (which is that Adam perceives Richard&rsquo;s interest in the ship), this isn&rsquo;t the text&rsquo;s main purpose. Rather, Adam&rsquo;s suggestion about where to sleep for the night serves as an example of the consideration Adam shows toward Richard, and the text mentions it mainly to explain how an affectionate relationship developed so quickly between them. Moreover, the text only states that Adam encourages Richard to stay on the ship; it doesn&rsquo;t specify where Adam plans to spend the night. Choice C is incorrect because the text doesn&rsquo;t describe why Adam and his great-uncle Richard are excited about their journey. While the text mentions that Adam is willing to &ldquo;start at any hour and go anywhere,&rdquo; it provides no details about any planned journey, its destination, or even whether they will be continuing by ship or some other mode of transportation, nor does the text mention anything about either character&rsquo;s feelings of excitement about their plans. We learn only that Adam is accommodating about potential travel plans, not that either character is particularly eager about the journey itself. The text&rsquo;s main focus is on Adam and Richard&rsquo;s developing relationship, not on any anticipated travel experiences. Choice D is incorrect because the text doesn&rsquo;t show a contrast between initial wariness and later affection. On the contrary, the text begins by stating that the meeting between Adam and his great-uncle Richard has begun in an &ldquo;auspicious,&rdquo; or promising, manner and is &ldquo;proceed[ing] well,&rdquo; suggesting that Richard&rsquo;s impression is positive from the outset. There&rsquo;s no indication of any initial suspicion, caution, or reserve on Richard&rsquo;s part that later changes to affection. Instead, the text describes a consistently positive interaction that deepens from a good first impression into a stronger, more familiar relationship because of Adam&rsquo;s considerate behavior.</p>$SATQ$, false, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, $SATQ${"questionId":"edbc6cca","external_id":"3a426293-3d0c-4938-8e24-6def7aeb6b41","vaultid":null,"uId":"a2f1a07d-3d07-453d-b6c4-efcca9499367","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"CAS","domain":"Craft and Structure","skill_cd":"TSP","skill_desc":"Text Structure and Purpose","difficulty":"E","score_band_range_cd":3,"type":"mcq","stimulus":"<p>The following text is from Bram Stoker&rsquo;s 1911 novel <em>The Lair of the White Worm</em>. Adam is meeting his great-uncle Richard at a port.</p>\n<blockquote>\n<p>The meeting so auspiciously begun proceeded well. Adam, seeing that the old man was interested in the novelty of the ship, suggested that he should stay the night on board, and that he would himself be ready to start at any hour and go anywhere that the other suggested. This affectionate willingness to fall in with his own plans quite won the old man&rsquo;s heart. He warmly accepted the invitation, and at once they became not only on terms of affectionate relationship, but almost like old friends.</p>\n</blockquote>","stem":"<p>Which choice best states the main purpose of the text?</p>","answerOptions":[{"id":"586588de-d5c0-4bde-9a7a-b67704fda2ab","content":"<p>It states the reasons why Adam and his great-uncle Richard decide to sleep on the ship rather than finding lodging on land.</p>"},{"id":"f38e81d1-1c66-492e-ab09-799c9c8ea411","content":"<p>It showcases how Adam&rsquo;s flexibility and consideration strengthen his relationship with his great-uncle Richard.</p>"},{"id":"1f95fc68-4478-4963-a308-3c46a6f3f551","content":"<p>It describes why Adam and his great-uncle Richard are excited for their upcoming journey on the ship.&nbsp;</p>"},{"id":"0eb2903c-db1d-48ac-91b1-e88369e54df8","content":"<p>It contrasts great-uncle Richard&rsquo;s wary first impressions of Adam with his ultimate affection toward him.</p>"}],"keys":["f38e81d1-1c66-492e-ab09-799c9c8ea411"],"correct_answer":["B"],"rationale":"<p>Choice B is the best answer because it most accurately describes the main purpose of the text, which is to showcase how Adam&rsquo;s flexibility and consideration strengthen his relationship with his great-uncle Richard. The text begins by stating that the meeting between the two characters is proceeding well and then describes Adam&rsquo;s thoughtful behavior: noticing his great-uncle&rsquo;s interest in the ship, Adam suggests staying on board overnight and expresses willingness to accommodate his great-uncle&rsquo;s schedule and destination preferences. The text goes on to describe the positive effect of Adam&rsquo;s thoughtfulness and flexibility, indicating that Adam&rsquo;s &ldquo;affectionate willingness&rdquo; to accommodate Richard&rsquo;s preferences &ldquo;quite won the old man&rsquo;s heart.&rdquo; The text concludes by suggesting that Adam&rsquo;s ability to anticipate his great-uncle&rsquo;s wishes and willingness to accommodate them result in the rapid development of affection and intimacy between them, stating that they soon became &ldquo;almost like old friends.&rdquo; Therefore, the text&rsquo;s main purpose is to demonstrate how Adam&rsquo;s flexibility and consideration strengthened his and his great-uncle&rsquo;s relationship.</p><p>Choice A is incorrect. Although the text explains Adam&rsquo;s reason for suggesting that Richard spend the night on the ship rather than finding lodging on land (which is that Adam perceives Richard&rsquo;s interest in the ship), this isn&rsquo;t the text&rsquo;s main purpose. Rather, Adam&rsquo;s suggestion about where to sleep for the night serves as an example of the consideration Adam shows toward Richard, and the text mentions it mainly to explain how an affectionate relationship developed so quickly between them. Moreover, the text only states that Adam encourages Richard to stay on the ship; it doesn&rsquo;t specify where Adam plans to spend the night. Choice C is incorrect because the text doesn&rsquo;t describe why Adam and his great-uncle Richard are excited about their journey. While the text mentions that Adam is willing to &ldquo;start at any hour and go anywhere,&rdquo; it provides no details about any planned journey, its destination, or even whether they will be continuing by ship or some other mode of transportation, nor does the text mention anything about either character&rsquo;s feelings of excitement about their plans. We learn only that Adam is accommodating about potential travel plans, not that either character is particularly eager about the journey itself. The text&rsquo;s main focus is on Adam and Richard&rsquo;s developing relationship, not on any anticipated travel experiences. Choice D is incorrect because the text doesn&rsquo;t show a contrast between initial wariness and later affection. On the contrary, the text begins by stating that the meeting between Adam and his great-uncle Richard has begun in an &ldquo;auspicious,&rdquo; or promising, manner and is &ldquo;proceed[ing] well,&rdquo; suggesting that Richard&rsquo;s impression is positive from the outset. There&rsquo;s no indication of any initial suspicion, caution, or reserve on Richard&rsquo;s part that later changes to affection. Instead, the text describes a consistently positive interaction that deepens from a good first impression into a stronger, more familiar relationship because of Adam&rsquo;s considerate behavior.</p>","parenttemplatename":null,"parenttemplateid":null,"templateclusterid":null,"templateclustername":null,"origin":null,"position":null,"createDate":1776362771168,"updateDate":1776362771168}$SATQ$::jsonb, 1776362771168, 1776362771168),
    ($SATQ$edd64a4a$SATQ$, $SATQ$9b93faf4-0537-4286-9930-2afe62d44731$SATQ$::uuid, NULL, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Craft and Structure$SATQ$, $SATQ$CAS$SATQ$, $SATQ$WIC$SATQ$, $SATQ$Words in Context$SATQ$, $SATQ$E$SATQ$, 1, $SATQ$mcq$SATQ$, $SATQ$<p>The following text is adapted from Charles Chesnutt&rsquo;s 1899 story &ldquo;The Wife of His Youth.&rdquo; Mr. Ryder is hosting a formal gathering where he will propose marriage to the woman he has been courting.</p>
<blockquote>
<p>[A] younger and less cautious man would long since have spoken. But he had made up his mind, and had only to <span role="region" aria-label="Referenced Content"><u>determine</u></span> the time when he would ask her to be his wife. He decided to give a ball in her honor, and at some time during the evening of the ball to offer her his heart and hand.</p>
</blockquote>$SATQ$, $SATQ$<p>As used in the text, what does the word &ldquo;determine&rdquo; most nearly mean?&nbsp;</p>$SATQ$, $SATQ$[{"id":"f4d9a680-dd66-4cf5-940c-a02a35ca03cf","content":"<p>Choose</p>"},{"id":"c9b3225a-1cf5-4750-a35a-3f9064b28a3e","content":"<p>Influence</p>"},{"id":"80d05a1f-3416-41de-99af-9926810d76b0","content":"<p>Demonstrate</p>"},{"id":"53fd68f1-1549-4f02-b323-828d48a11010","content":"<p>Measure</p>"}]$SATQ$::jsonb, $SATQ$["A"]$SATQ$::jsonb, $SATQ$["f4d9a680-dd66-4cf5-940c-a02a35ca03cf"]$SATQ$::jsonb, $SATQ$<p>Choice A is the best answer because as used in the text, "determine" most nearly means choose or decide. The text indicates that Mr. Ryder "had made up his mind" to ask a woman to marry him but had not yet "spoken"&mdash;that is, he had not yet asked her. The text also indicates that Mr. Ryder "decided" to throw a party for the woman and ask her during it. This context conveys that after making up his mind to propose, what Mr. Ryder had to do was determine, or choose, the time to do it.</p><p>Choice B is incorrect because in this context, "determine" doesn&rsquo;t mean influence, or affect or control. The text isn&rsquo;t indicating that Mr. Ryder is controlling time itself; such a thing isn&rsquo;t possible. Rather, the text conveys that after making up his mind to ask a woman to marry him, Mr. Ryder had to make another decision about his own actions by selecting a time to propose. Choice C is incorrect. The text focuses on Mr. Ryder&rsquo;s plan to ask a woman to marry him and his decision about when to ask her. This context conveys that after making up his mind to propose, Mr. Ryder had to choose the time, not that he had to demonstrate, or show, the time; it&rsquo;s not clear what it would mean to demonstrate a time. Choice D is incorrect because in this context, "determine" doesn&rsquo;t mean measure, or control with careful restraint. The text isn&rsquo;t indicating that Mr. Ryder is carefully controlling time itself; such a thing isn&rsquo;t possible. Rather, the text conveys that after making up his mind to ask a woman to marry him, Mr. Ryder had to make another decision about his own actions by selecting a time to propose; it&rsquo;s Mr. Ryder&rsquo;s decision that is measured, not the time he eventually chooses.</p>$SATQ$, false, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, $SATQ${"questionId":"edd64a4a","external_id":"9b93faf4-0537-4286-9930-2afe62d44731","vaultid":null,"uId":"6b3f7e26-9666-4a1b-8e58-3a8462cde7c0","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"CAS","domain":"Craft and Structure","skill_cd":"WIC","skill_desc":"Words in Context","difficulty":"E","score_band_range_cd":1,"type":"mcq","stimulus":"<p>The following text is adapted from Charles Chesnutt&rsquo;s 1899 story &ldquo;The Wife of His Youth.&rdquo; Mr. Ryder is hosting a formal gathering where he will propose marriage to the woman he has been courting.</p>\n<blockquote>\n<p>[A] younger and less cautious man would long since have spoken. But he had made up his mind, and had only to <span role=\"region\" aria-label=\"Referenced Content\"><u>determine</u></span> the time when he would ask her to be his wife. He decided to give a ball in her honor, and at some time during the evening of the ball to offer her his heart and hand.</p>\n</blockquote>","stem":"<p>As used in the text, what does the word &ldquo;determine&rdquo; most nearly mean?&nbsp;</p>","answerOptions":[{"id":"f4d9a680-dd66-4cf5-940c-a02a35ca03cf","content":"<p>Choose</p>"},{"id":"c9b3225a-1cf5-4750-a35a-3f9064b28a3e","content":"<p>Influence</p>"},{"id":"80d05a1f-3416-41de-99af-9926810d76b0","content":"<p>Demonstrate</p>"},{"id":"53fd68f1-1549-4f02-b323-828d48a11010","content":"<p>Measure</p>"}],"keys":["f4d9a680-dd66-4cf5-940c-a02a35ca03cf"],"correct_answer":["A"],"rationale":"<p>Choice A is the best answer because as used in the text, \"determine\" most nearly means choose or decide. The text indicates that Mr. Ryder \"had made up his mind\" to ask a woman to marry him but had not yet \"spoken\"&mdash;that is, he had not yet asked her. The text also indicates that Mr. Ryder \"decided\" to throw a party for the woman and ask her during it. This context conveys that after making up his mind to propose, what Mr. Ryder had to do was determine, or choose, the time to do it.</p><p>Choice B is incorrect because in this context, \"determine\" doesn&rsquo;t mean influence, or affect or control. The text isn&rsquo;t indicating that Mr. Ryder is controlling time itself; such a thing isn&rsquo;t possible. Rather, the text conveys that after making up his mind to ask a woman to marry him, Mr. Ryder had to make another decision about his own actions by selecting a time to propose. Choice C is incorrect. The text focuses on Mr. Ryder&rsquo;s plan to ask a woman to marry him and his decision about when to ask her. This context conveys that after making up his mind to propose, Mr. Ryder had to choose the time, not that he had to demonstrate, or show, the time; it&rsquo;s not clear what it would mean to demonstrate a time. Choice D is incorrect because in this context, \"determine\" doesn&rsquo;t mean measure, or control with careful restraint. The text isn&rsquo;t indicating that Mr. Ryder is carefully controlling time itself; such a thing isn&rsquo;t possible. Rather, the text conveys that after making up his mind to ask a woman to marry him, Mr. Ryder had to make another decision about his own actions by selecting a time to propose; it&rsquo;s Mr. Ryder&rsquo;s decision that is measured, not the time he eventually chooses.</p>","parenttemplatename":null,"parenttemplateid":null,"templateclusterid":null,"templateclustername":null,"origin":null,"position":null,"createDate":1730147323031,"updateDate":1730147323031}$SATQ$::jsonb, 1730147323031, 1730147323031),
    ($SATQ$f0ae0da3$SATQ$, $SATQ$918ce129-70e2-4dee-86da-06f2ab0444b0$SATQ$::uuid, NULL, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Craft and Structure$SATQ$, $SATQ$CAS$SATQ$, $SATQ$CTC$SATQ$, $SATQ$Cross-Text Connections$SATQ$, $SATQ$M$SATQ$, 5, $SATQ$mcq$SATQ$, $SATQ$<p><span class="paired_passage" role="heading" aria-level="2"><strong>Text 1</strong></span></p>
<p>When companies in the same industry propose merging with one another, they often claim that the merger will benefit consumers by increasing efficiency and therefore lowering prices. Economist Ying Fan investigated this notion in the context of the United States newspaper market. She modeled a hypothetical merger of Minneapolis-area newspapers and found that subscription prices would rise following a merger.</p>
<p>&nbsp;</p>
<p><span class="paired_passage" role="heading" aria-level="2"><strong>Text 2</strong></span></p>
<p>Economists Dario Focarelli and Fabio Panetta have argued that research on the effect of mergers on prices has focused excessively on short-term effects, which tend to be adverse for consumers. Using the case of consumer banking in Italy, they show that over the long term (several years, in their study), the efficiency gains realized by merged companies do result in economic benefits for consumers.&nbsp;</p>$SATQ$, $SATQ$<p>Based on the texts, how would Focarelli and Panetta (Text 2) most likely respond to Fan&rsquo;s findings (Text 1)?</p>$SATQ$, $SATQ$[{"id":"d7d47a2a-b424-4e40-8906-5395e6ce8385","content":"<p>They would recommend that Fan compare the near-term effect of a merger on subscription prices in the Minneapolis area with the effect of a merger in another newspaper market.</p>"},{"id":"2541e29d-0e42-4166-9b8e-0492ffd37424","content":"<p>They would argue that over the long term the expenses incurred by the merged newspaper company will also increase.</p>"},{"id":"5a8f70de-70d6-4405-b837-22dd1b23a770","content":"<p>They would encourage Fan to investigate whether the projected effect on subscription prices persists over an extended period.</p>"},{"id":"b5bd0a9c-a2c8-429a-9f42-5a181e76b0cf","content":"<p>They would claim that mergers have a different effect on consumer prices in the newspaper industry than in most other industries.&nbsp;</p>"}]$SATQ$::jsonb, $SATQ$["C"]$SATQ$::jsonb, $SATQ$["5a8f70de-70d6-4405-b837-22dd1b23a770"]$SATQ$::jsonb, $SATQ$<p>Choice C is the best answer because, based on the information presented in the texts, it represents how Focarelli and Panetta would most likely respond to Fan&rsquo;s findings. Text 1 indicates that Fan found that a newspaper merger would result in a rise in subscription prices. This rise wouldn&rsquo;t benefit customers, who would have to pay more for news after a merger. Text 2 presents Focarelli and Panetta&rsquo;s argument that merger research tends to focus too much on what happens immediately after the merger. Text 2 goes on to describe their finding that mergers can be economically beneficial for consumers over the long term. This suggests that Focarelli and Panetta would encourage Fan to investigate the long-term effect of the hypothetical newspaper merger on subscription prices.</p><p>Choice A is incorrect because Text 2 doesn&rsquo;t indicate that Focarelli and Panetta connect the effects of mergers to specific locations. Instead, Focarelli and Panetta focus on the length of time over which the effects of mergers should be evaluated. Choice B is incorrect because Text 2 indicates that Focarelli and Panetta found that merged companies experience "efficiency gains" over the long term, meaning that their expenses go down relative to their output, not that their expenses increase. Choice D is incorrect because there&rsquo;s no indication in Text 2 that Focarelli and Panetta believe that the newspaper industry is different from any other industry when it comes to the effects of mergers. Although their own research was about consumer banking, Text 2 suggests that they view their conclusions as applicable to mergers in general.</p>$SATQ$, false, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, $SATQ${"questionId":"f0ae0da3","external_id":"918ce129-70e2-4dee-86da-06f2ab0444b0","vaultid":null,"uId":"aacf24a4-5937-43ca-89dc-c17c80ec7173","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"CAS","domain":"Craft and Structure","skill_cd":"CTC","skill_desc":"Cross-Text Connections","difficulty":"M","score_band_range_cd":5,"type":"mcq","stimulus":"<p><span class=\"paired_passage\" role=\"heading\" aria-level=\"2\"><strong>Text 1</strong></span></p>\n<p>When companies in the same industry propose merging with one another, they often claim that the merger will benefit consumers by increasing efficiency and therefore lowering prices. Economist Ying Fan investigated this notion in the context of the United States newspaper market. She modeled a hypothetical merger of Minneapolis-area newspapers and found that subscription prices would rise following a merger.</p>\n<p>&nbsp;</p>\n<p><span class=\"paired_passage\" role=\"heading\" aria-level=\"2\"><strong>Text 2</strong></span></p>\n<p>Economists Dario Focarelli and Fabio Panetta have argued that research on the effect of mergers on prices has focused excessively on short-term effects, which tend to be adverse for consumers. Using the case of consumer banking in Italy, they show that over the long term (several years, in their study), the efficiency gains realized by merged companies do result in economic benefits for consumers.&nbsp;</p>","stem":"<p>Based on the texts, how would Focarelli and Panetta (Text 2) most likely respond to Fan&rsquo;s findings (Text 1)?</p>","answerOptions":[{"id":"d7d47a2a-b424-4e40-8906-5395e6ce8385","content":"<p>They would recommend that Fan compare the near-term effect of a merger on subscription prices in the Minneapolis area with the effect of a merger in another newspaper market.</p>"},{"id":"2541e29d-0e42-4166-9b8e-0492ffd37424","content":"<p>They would argue that over the long term the expenses incurred by the merged newspaper company will also increase.</p>"},{"id":"5a8f70de-70d6-4405-b837-22dd1b23a770","content":"<p>They would encourage Fan to investigate whether the projected effect on subscription prices persists over an extended period.</p>"},{"id":"b5bd0a9c-a2c8-429a-9f42-5a181e76b0cf","content":"<p>They would claim that mergers have a different effect on consumer prices in the newspaper industry than in most other industries.&nbsp;</p>"}],"keys":["5a8f70de-70d6-4405-b837-22dd1b23a770"],"correct_answer":["C"],"rationale":"<p>Choice C is the best answer because, based on the information presented in the texts, it represents how Focarelli and Panetta would most likely respond to Fan&rsquo;s findings. Text 1 indicates that Fan found that a newspaper merger would result in a rise in subscription prices. This rise wouldn&rsquo;t benefit customers, who would have to pay more for news after a merger. Text 2 presents Focarelli and Panetta&rsquo;s argument that merger research tends to focus too much on what happens immediately after the merger. Text 2 goes on to describe their finding that mergers can be economically beneficial for consumers over the long term. This suggests that Focarelli and Panetta would encourage Fan to investigate the long-term effect of the hypothetical newspaper merger on subscription prices.</p><p>Choice A is incorrect because Text 2 doesn&rsquo;t indicate that Focarelli and Panetta connect the effects of mergers to specific locations. Instead, Focarelli and Panetta focus on the length of time over which the effects of mergers should be evaluated. Choice B is incorrect because Text 2 indicates that Focarelli and Panetta found that merged companies experience \"efficiency gains\" over the long term, meaning that their expenses go down relative to their output, not that their expenses increase. Choice D is incorrect because there&rsquo;s no indication in Text 2 that Focarelli and Panetta believe that the newspaper industry is different from any other industry when it comes to the effects of mergers. Although their own research was about consumer banking, Text 2 suggests that they view their conclusions as applicable to mergers in general.</p>","parenttemplatename":null,"parenttemplateid":null,"templateclusterid":null,"templateclustername":null,"origin":null,"position":null,"createDate":1691007959311,"updateDate":1691007959311}$SATQ$::jsonb, 1691007959311, 1691007959311),
    ($SATQ$f0be91b2$SATQ$, $SATQ$2e39c6e2-51e8-4fa5-9d27-6da71b094057$SATQ$::uuid, NULL, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Craft and Structure$SATQ$, $SATQ$CAS$SATQ$, $SATQ$WIC$SATQ$, $SATQ$Words in Context$SATQ$, $SATQ$M$SATQ$, 5, $SATQ$mcq$SATQ$, $SATQ$<p>Drivers who strongly believe that the toll they must pay to use the Lewis and Clark Bridge, which spans the Ohio River to connect Indiana and Kentucky, is currently too high are unlikely to be <span aria-hidden="true">______</span><span class="sr-only">blank</span> a proposal to increase the toll. Advocates for a higher toll are likely to have more success if they instead direct their arguments toward a more persuadable segment of the population.&nbsp;</p>$SATQ$, $SATQ$<p>Which choice completes the text with the most logical and precise word or phrase?</p>$SATQ$, $SATQ$[{"id":"bd241a21-c5f3-455c-8b5d-b569650df974","content":"<p>receptive to</p>"},{"id":"83eda3b8-69f9-4c8a-98ba-9c14b8246679","content":"<p>apprised of</p>"},{"id":"d5c222b1-ffde-448d-9938-eff80f9dd051","content":"<p>incensed by</p>"},{"id":"e211eff8-ea9e-4576-bcd0-d957af9658ac","content":"<p>cited in</p>"}]$SATQ$::jsonb, $SATQ$["A"]$SATQ$::jsonb, $SATQ$["bd241a21-c5f3-455c-8b5d-b569650df974"]$SATQ$::jsonb, $SATQ$<p>Choice A is the best answer because it most logically completes the text&rsquo;s discussion of driver attitudes toward a toll increase. In this context, "receptive to" would mean open to or willing to consider something. The text focuses on drivers who think the current toll for the Lewis and Clark Bridge is too high, suggesting that advocates for increasing that toll would have better success presenting their arguments to "a more persuadable segment of the population" rather than to those drivers. This context suggests that the drivers who strongly believe the toll is already too high are not persuadable&mdash;that is, that they are unlikely to be willing to consider the toll-increase proposal.</p><p>Choice B is incorrect because "apprised of" means informed about or made aware of something, and nothing in the text suggests that the drivers who think a toll is already too high wouldn&rsquo;t be informed of a proposal for an even higher toll; in fact, the text implies that advocates of the proposal would "direct their arguments" in favor of the increase to those drivers, even though they would likely be more successful focusing on people who are more open to hearing their arguments. Choice C is incorrect. In this context, "incensed by" would mean angered or outraged by something. The text focuses on drivers who feel that a current toll is too high, and it wouldn&rsquo;t make sense to suggest that those drivers would be <em>unlikely </em>to be angered by a proposal for the toll to be increased; indeed, drivers who think the toll is already too high likely would be angered by a move to raise it even higher. Choice D is incorrect. In this context, "cited in" would mean referred to or mentioned in something. Although it&rsquo;s reasonable to suggest that a proposal to raise a toll might not make any mention of drivers who think the toll is already too high, the text focuses on how those drivers and other people are likely to react to arguments in favor of the proposal, not on whether those drivers would be cited in the proposal itself.</p>$SATQ$, false, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, $SATQ${"questionId":"f0be91b2","external_id":"2e39c6e2-51e8-4fa5-9d27-6da71b094057","vaultid":null,"uId":"030498e3-79dc-4b6d-a0a9-b0ca5abadb32","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"CAS","domain":"Craft and Structure","skill_cd":"WIC","skill_desc":"Words in Context","difficulty":"M","score_band_range_cd":5,"type":"mcq","stimulus":"<p>Drivers who strongly believe that the toll they must pay to use the Lewis and Clark Bridge, which spans the Ohio River to connect Indiana and Kentucky, is currently too high are unlikely to be <span aria-hidden=\"true\">______</span><span class=\"sr-only\">blank</span> a proposal to increase the toll. Advocates for a higher toll are likely to have more success if they instead direct their arguments toward a more persuadable segment of the population.&nbsp;</p>","stem":"<p>Which choice completes the text with the most logical and precise word or phrase?</p>","answerOptions":[{"id":"bd241a21-c5f3-455c-8b5d-b569650df974","content":"<p>receptive to</p>"},{"id":"83eda3b8-69f9-4c8a-98ba-9c14b8246679","content":"<p>apprised of</p>"},{"id":"d5c222b1-ffde-448d-9938-eff80f9dd051","content":"<p>incensed by</p>"},{"id":"e211eff8-ea9e-4576-bcd0-d957af9658ac","content":"<p>cited in</p>"}],"keys":["bd241a21-c5f3-455c-8b5d-b569650df974"],"correct_answer":["A"],"rationale":"<p>Choice A is the best answer because it most logically completes the text&rsquo;s discussion of driver attitudes toward a toll increase. In this context, \"receptive to\" would mean open to or willing to consider something. The text focuses on drivers who think the current toll for the Lewis and Clark Bridge is too high, suggesting that advocates for increasing that toll would have better success presenting their arguments to \"a more persuadable segment of the population\" rather than to those drivers. This context suggests that the drivers who strongly believe the toll is already too high are not persuadable&mdash;that is, that they are unlikely to be willing to consider the toll-increase proposal.</p><p>Choice B is incorrect because \"apprised of\" means informed about or made aware of something, and nothing in the text suggests that the drivers who think a toll is already too high wouldn&rsquo;t be informed of a proposal for an even higher toll; in fact, the text implies that advocates of the proposal would \"direct their arguments\" in favor of the increase to those drivers, even though they would likely be more successful focusing on people who are more open to hearing their arguments. Choice C is incorrect. In this context, \"incensed by\" would mean angered or outraged by something. The text focuses on drivers who feel that a current toll is too high, and it wouldn&rsquo;t make sense to suggest that those drivers would be <em>unlikely </em>to be angered by a proposal for the toll to be increased; indeed, drivers who think the toll is already too high likely would be angered by a move to raise it even higher. Choice D is incorrect. In this context, \"cited in\" would mean referred to or mentioned in something. Although it&rsquo;s reasonable to suggest that a proposal to raise a toll might not make any mention of drivers who think the toll is already too high, the text focuses on how those drivers and other people are likely to react to arguments in favor of the proposal, not on whether those drivers would be cited in the proposal itself.</p>","parenttemplatename":null,"parenttemplateid":null,"templateclusterid":null,"templateclustername":null,"origin":null,"position":null,"createDate":1755117061176,"updateDate":1755117061176}$SATQ$::jsonb, 1755117061176, 1755117061176),
    ($SATQ$f1c9d2c1$SATQ$, $SATQ$c84de96f-8a11-4841-b4c1-2d551188f74f$SATQ$::uuid, $SATQ$7165ce7a-911b-4d5a-830b-68322b13e31f$SATQ$::uuid, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Craft and Structure$SATQ$, $SATQ$CAS$SATQ$, $SATQ$CTC$SATQ$, $SATQ$Cross-Text Connections$SATQ$, $SATQ$M$SATQ$, 4, $SATQ$mcq$SATQ$, $SATQ$<p><strong>Text 1</strong></p>
<p>Stage lighting theorist Adolphe Appia was perhaps the first to argue that light must be considered alongside all the various elements of a stage to create a single, unified performance. Researcher Kelly Bremner, however, has noted that Appia lacked technical expertise in the use of light in the theater. As a result of Appia&rsquo;s inexperience, Bremner argues, Appia&rsquo;s theory of light called for lighting practices that weren&rsquo;t possible until after the advent of electricity around 1881.&nbsp;</p>
<p>&nbsp;</p>
<p><strong>Text 2</strong></p>
<p>Adolphe Appia was not an amateur in the practice of lighting. Instead, it is precisely his exposure to lighting techniques at the time that contributed to his theory on the importance of light. When working as an apprentice for a lighting specialist in his youth, Appia observed the use of portable lighting devices that could be operated by hand. This experience developed his understanding of what was possible in the coordination of elements on the stage.</p>$SATQ$, $SATQ$<p>Based on the texts, how would the author of Text 2 most likely respond to the claim about Appia&rsquo;s level of technical expertise made by Bremner in Text 1?</p>$SATQ$, $SATQ$[{"id":"6184d799-d3d6-46c3-b242-27e8dfd78aaa","content":"<p>Many lighting technicians dismissed Appia&rsquo;s ideas about light on the stage.</p>"},{"id":"9ca5549e-6c94-404c-bf01-d4284916442e","content":"<p>Appia likely gained a level of technical expertise during his time as an apprentice.</p>"},{"id":"0f5ff2f4-6562-45e3-bb10-c879429b2b41","content":"<p>Theater practitioners who worked with Appia greatly admired his work.</p>"},{"id":"16c73d00-4974-4833-865e-f49ac4b367e2","content":"<p>Appia was unfamiliar with the use of music and sound in theater.</p>"}]$SATQ$::jsonb, $SATQ$["B"]$SATQ$::jsonb, $SATQ$["9ca5549e-6c94-404c-bf01-d4284916442e"]$SATQ$::jsonb, $SATQ$<p>Choice B is the best answer. The author of Text 2 directly contradicts Bremner&rsquo;s claim that Appia lacked technical expertise by stating that Appia was &ldquo;not an amateur in the practice of lighting.&rdquo; His experience as a lighting specialist&rsquo;s apprentice would have, the author of Text 2 argues, allowed Appia to &ldquo;[develop] his understanding of what was possible&rdquo; with the elements of theatrical design. </p><p>Choice A is incorrect. Neither text describes how other lighting technicians responded to Appia&rsquo;s ideas. Furthermore, this claim isn&rsquo;t relevant to Bremner&rsquo;s evaluation of Appia&rsquo;s technical expertise. Choice C is incorrect. Neither text mentions anything about the opinions of theater practitioners who worked with Appia, so this answer choice does not relate to the claim about Appia&rsquo;s level of technical expertise made by Bremner in Text 1. Choice D is incorrect. Neither text mentions anything about Appia&rsquo;s familiarity with or ignorance of the use of music and sound in theater. Both focus on his expertise (or lack thereof) in lighting. </p>$SATQ$, false, 0, $SATQ$OSP-KA-CTC-M006$SATQ$, $SATQ$$SATQ$, $SATQ$1af6d414-8ded-4159-b13e-a2ad80f7952d$SATQ$::uuid, $SATQ$$SATQ$, $SATQ$proteus$SATQ$, $SATQ$0$SATQ$, NULL, NULL, $SATQ${"questionId":"f1c9d2c1","external_id":"c84de96f-8a11-4841-b4c1-2d551188f74f","vaultid":"7165ce7a-911b-4d5a-830b-68322b13e31f","uId":"8845055c-be60-4043-8430-fe544c279cf1","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"CAS","domain":"Craft and Structure","skill_cd":"CTC","skill_desc":"Cross-Text Connections","difficulty":"M","score_band_range_cd":4,"type":"mcq","stimulus":"<p><strong>Text 1</strong></p>\n<p>Stage lighting theorist Adolphe Appia was perhaps the first to argue that light must be considered alongside all the various elements of a stage to create a single, unified performance. Researcher Kelly Bremner, however, has noted that Appia lacked technical expertise in the use of light in the theater. As a result of Appia&rsquo;s inexperience, Bremner argues, Appia&rsquo;s theory of light called for lighting practices that weren&rsquo;t possible until after the advent of electricity around 1881.&nbsp;</p>\n<p>&nbsp;</p>\n<p><strong>Text 2</strong></p>\n<p>Adolphe Appia was not an amateur in the practice of lighting. Instead, it is precisely his exposure to lighting techniques at the time that contributed to his theory on the importance of light. When working as an apprentice for a lighting specialist in his youth, Appia observed the use of portable lighting devices that could be operated by hand. This experience developed his understanding of what was possible in the coordination of elements on the stage.</p>","stem":"<p>Based on the texts, how would the author of Text 2 most likely respond to the claim about Appia&rsquo;s level of technical expertise made by Bremner in Text 1?</p>","answerOptions":[{"id":"6184d799-d3d6-46c3-b242-27e8dfd78aaa","content":"<p>Many lighting technicians dismissed Appia&rsquo;s ideas about light on the stage.</p>"},{"id":"9ca5549e-6c94-404c-bf01-d4284916442e","content":"<p>Appia likely gained a level of technical expertise during his time as an apprentice.</p>"},{"id":"0f5ff2f4-6562-45e3-bb10-c879429b2b41","content":"<p>Theater practitioners who worked with Appia greatly admired his work.</p>"},{"id":"16c73d00-4974-4833-865e-f49ac4b367e2","content":"<p>Appia was unfamiliar with the use of music and sound in theater.</p>"}],"keys":["9ca5549e-6c94-404c-bf01-d4284916442e"],"correct_answer":["B"],"rationale":"<p>Choice B is the best answer. The author of Text 2 directly contradicts Bremner&rsquo;s claim that Appia lacked technical expertise by stating that Appia was &ldquo;not an amateur in the practice of lighting.&rdquo; His experience as a lighting specialist&rsquo;s apprentice would have, the author of Text 2 argues, allowed Appia to &ldquo;[develop] his understanding of what was possible&rdquo; with the elements of theatrical design. </p><p>Choice A is incorrect. Neither text describes how other lighting technicians responded to Appia&rsquo;s ideas. Furthermore, this claim isn&rsquo;t relevant to Bremner&rsquo;s evaluation of Appia&rsquo;s technical expertise. Choice C is incorrect. Neither text mentions anything about the opinions of theater practitioners who worked with Appia, so this answer choice does not relate to the claim about Appia&rsquo;s level of technical expertise made by Bremner in Text 1. Choice D is incorrect. Neither text mentions anything about Appia&rsquo;s familiarity with or ignorance of the use of music and sound in theater. Both focus on his expertise (or lack thereof) in lighting. </p>","parenttemplatename":"OSP-KA-CTC-M006","parenttemplateid":"","templateclusterid":"1af6d414-8ded-4159-b13e-a2ad80f7952d","templateclustername":"","origin":"proteus","position":"0","createDate":1691007959366,"updateDate":1691007959366}$SATQ$::jsonb, 1691007959366, 1691007959366),
    ($SATQ$f2c48e47$SATQ$, $SATQ$6a07c552-55b8-4327-80fc-4e6817708953$SATQ$::uuid, $SATQ$3ae9c98b-738b-4fa8-ac2b-b5ce3a56b9fd$SATQ$::uuid, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Craft and Structure$SATQ$, $SATQ$CAS$SATQ$, $SATQ$TSP$SATQ$, $SATQ$Text Structure and Purpose$SATQ$, $SATQ$M$SATQ$, 5, $SATQ$mcq$SATQ$, $SATQ$<p>The following text is from Charlotte Perkins Gilman&rsquo;s 1910 poem &ldquo;The Earth&rsquo;s Entail.&rdquo;</p>
<p>No matter how we cultivate the land,</p>
<p> Taming the forest and the prairie free;</p>
<p>No matter how we irrigate the sand,</p>
<p>Making the desert blossom at command,</p>
<p>&nbsp;We must always leave the borders of the sea;</p>
<p>&nbsp;The immeasureable reaches</p>
<p>&nbsp;Of the windy wave-wet beaches,</p>
<p>The million-mile-long margin of the sea.</p>$SATQ$, $SATQ$<p>Which choice best describes the overall structure of the text?</p>$SATQ$, $SATQ$[{"id":"fe2684de-935e-436f-b285-8da2b0b65874","content":"<p>The speaker argues against interfering with nature and then gives evidence supporting this interference.</p>"},{"id":"28b967b3-7cd7-4d38-b58a-426f50d715dc","content":"<p>The speaker presents an account of efforts to dominate nature and then cautions that such efforts are only temporary.</p>"},{"id":"74eed7a5-c6e6-4d08-8ff0-7cc0fee5c856","content":"<p>The speaker provides examples of an admirable way of approaching nature and then challenges that approach.&nbsp;</p>"},{"id":"5604c9a8-363f-41f6-b2d7-06bf6d4625d4","content":"<p>The speaker describes attempts to control nature and then offers a reminder that not all nature is controllable.&nbsp;</p>"}]$SATQ$::jsonb, $SATQ$["D"]$SATQ$::jsonb, $SATQ$["5604c9a8-363f-41f6-b2d7-06bf6d4625d4"]$SATQ$::jsonb, $SATQ$<p>Choice D is the best answer. This best describes the overall structure of the text. In the first half of the text, the speaker describes our attempts to control nature: cultivating, taming, and irrigating different kinds of land. In the second half, the speaker states that we can never tame the sea or the beach.&nbsp;</p><p>Choice A is incorrect. This doesn&rsquo;t describe the overall structure of the text. The speaker never argues that we should not interfere with nature. Rather, the speaker says that we are able to tame many different kinds of land, but we are unable to tame the sea or beaches.&nbsp;Choice B is incorrect. This doesn&rsquo;t describe the overall structure of the text. The speaker never describes our cultivation, taming, and irrigation of land as &ldquo;temporary.&rdquo; Rather, the speaker says that we are able to tame many different kinds of land, but we are unable to tame the sea or beaches.&nbsp;Choice C is incorrect. This doesn&rsquo;t describe the overall structure of the text. The speaker never describes our cultivation, taming, and irrigation of land as an &ldquo;admirable&rdquo; approach to nature.&rdquo; Rather, the speaker says that we are able to tame many different kinds of land, but we are unable to tame the sea or beaches.&nbsp;</p>$SATQ$, false, 0, $SATQ$OSP-022-TSP$SATQ$, $SATQ$$SATQ$, $SATQ$2cfdaeca-d151-4618-81e7-e1e0ce248a38$SATQ$::uuid, $SATQ$$SATQ$, $SATQ$proteus$SATQ$, $SATQ$0$SATQ$, NULL, NULL, $SATQ${"questionId":"f2c48e47","external_id":"6a07c552-55b8-4327-80fc-4e6817708953","vaultid":"3ae9c98b-738b-4fa8-ac2b-b5ce3a56b9fd","uId":"86098b00-368a-4b50-a487-f5018dae5073","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"CAS","domain":"Craft and Structure","skill_cd":"TSP","skill_desc":"Text Structure and Purpose","difficulty":"M","score_band_range_cd":5,"type":"mcq","stimulus":"<p>The following text is from Charlotte Perkins Gilman&rsquo;s 1910 poem &ldquo;The Earth&rsquo;s Entail.&rdquo;</p>\n<p>No matter how we cultivate the land,</p>\n<p> Taming the forest and the prairie free;</p>\n<p>No matter how we irrigate the sand,</p>\n<p>Making the desert blossom at command,</p>\n<p>&nbsp;We must always leave the borders of the sea;</p>\n<p>&nbsp;The immeasureable reaches</p>\n<p>&nbsp;Of the windy wave-wet beaches,</p>\n<p>The million-mile-long margin of the sea.</p>","stem":"<p>Which choice best describes the overall structure of the text?</p>","answerOptions":[{"id":"fe2684de-935e-436f-b285-8da2b0b65874","content":"<p>The speaker argues against interfering with nature and then gives evidence supporting this interference.</p>"},{"id":"28b967b3-7cd7-4d38-b58a-426f50d715dc","content":"<p>The speaker presents an account of efforts to dominate nature and then cautions that such efforts are only temporary.</p>"},{"id":"74eed7a5-c6e6-4d08-8ff0-7cc0fee5c856","content":"<p>The speaker provides examples of an admirable way of approaching nature and then challenges that approach.&nbsp;</p>"},{"id":"5604c9a8-363f-41f6-b2d7-06bf6d4625d4","content":"<p>The speaker describes attempts to control nature and then offers a reminder that not all nature is controllable.&nbsp;</p>"}],"keys":["5604c9a8-363f-41f6-b2d7-06bf6d4625d4"],"correct_answer":["D"],"rationale":"<p>Choice D is the best answer. This best describes the overall structure of the text. In the first half of the text, the speaker describes our attempts to control nature: cultivating, taming, and irrigating different kinds of land. In the second half, the speaker states that we can never tame the sea or the beach.&nbsp;</p><p>Choice A is incorrect. This doesn&rsquo;t describe the overall structure of the text. The speaker never argues that we should not interfere with nature. Rather, the speaker says that we are able to tame many different kinds of land, but we are unable to tame the sea or beaches.&nbsp;Choice B is incorrect. This doesn&rsquo;t describe the overall structure of the text. The speaker never describes our cultivation, taming, and irrigation of land as &ldquo;temporary.&rdquo; Rather, the speaker says that we are able to tame many different kinds of land, but we are unable to tame the sea or beaches.&nbsp;Choice C is incorrect. This doesn&rsquo;t describe the overall structure of the text. The speaker never describes our cultivation, taming, and irrigation of land as an &ldquo;admirable&rdquo; approach to nature.&rdquo; Rather, the speaker says that we are able to tame many different kinds of land, but we are unable to tame the sea or beaches.&nbsp;</p>","parenttemplatename":"OSP-022-TSP","parenttemplateid":"","templateclusterid":"2cfdaeca-d151-4618-81e7-e1e0ce248a38","templateclustername":"","origin":"proteus","position":"0","createDate":1691007959317,"updateDate":1691007959317}$SATQ$::jsonb, 1691007959317, 1691007959317),
    ($SATQ$f3c45b4f$SATQ$, $SATQ$1654cd84-f39b-43db-80e8-cf0e6d4b9926$SATQ$::uuid, $SATQ$20a4b285-1975-4262-b8c6-7c50dd9fdeb1$SATQ$::uuid, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Craft and Structure$SATQ$, $SATQ$CAS$SATQ$, $SATQ$CTC$SATQ$, $SATQ$Cross-Text Connections$SATQ$, $SATQ$H$SATQ$, 6, $SATQ$mcq$SATQ$, $SATQ$<p><strong>Text 1</strong></p>
<p>Fossils of the hominin <em>Australopithecus africanus</em> have been found in the Sterkfontein Caves of South Africa, but <span style="text-decoration: underline;">assigning an age to the fossils is challenging because of the unreliability of dating methods in this context.</span> The geology of Sterkfontein has caused soil layers from different periods to mix, impeding stratigraphic dating, and dates cannot be reliably imputed from those of nearby animal bones since the bones may have been relocated by flooding.</p>
<p><strong>Text 2</strong></p>
<p>Archaeologists used new cosmogenic nuclide dating techniques to reevaluate the ages of <em>A. africanus</em> fossils found in the Sterkfontein Caves. This technique involves analyzing the cosmogenic nucleotides in the breccia&mdash;the matrix of rock fragments immediately surrounding the fossils. The researchers assert that this approach avoids the potential for misdating associated with assigning ages based on Sterkfontein&rsquo;s soil layers or animal bones.</p>$SATQ$, $SATQ$<p>Based on the texts, how would the researchers in Text 2 most likely respond to the underlined portion in Text 1?</p>$SATQ$, $SATQ$[{"id":"2fdf5c0b-8a9a-44ac-9c9c-3b798f9c9293","content":"<p>They would emphasize the fact that the <em>A. africanus</em> fossils found in the Sterkfontein Caves may have been corrupted in some way over the years.</p>"},{"id":"244034a2-6dc6-4416-90e0-63ec7cc964e0","content":"<p>They would contend that if analyses of surrounding layers and bones in the Sterkfontein Caves were combined, then the dating of the fossils there would be more accurate.&nbsp;</p>"},{"id":"f8beaf83-4f3f-4929-a380-3318aaa9d79b","content":"<p>They would argue that their techniques are better suited than other methods to the unique challenges posed by the Sterkfontein Caves.</p>"},{"id":"ca24f52f-cc02-4735-9bfe-7f3d6a748c37","content":"<p>They would claim that cosmogenic nuclide dating is reliable in the context of the Sterkfontein Caves because it is applied to the fossils directly.</p>"}]$SATQ$::jsonb, $SATQ$["C"]$SATQ$::jsonb, $SATQ$["f8beaf83-4f3f-4929-a380-3318aaa9d79b"]$SATQ$::jsonb, $SATQ$<p>Choice C is the best answer. Text 2 states that the researchers used cosmogenic nuclide dating to "avoid the potential for misdating" caused by the geology of Sterkfontein, which Text 1 describes as "challenging" and unreliable.</p><p>Choice A is incorrect. Neither text suggests that the <em>A.</em> <em>africanus</em> fossils have been "corrupted," but only that traditional dating methods are difficult in Sterkfontein because of floods and soil mixing where the fossils were found. Nothing is implied to have compromised the fossils themselves. Choice B is incorrect. This choice misreads Text 2. Text 2 agrees that stratigraphy and other methods are prone to error in the context of Sterkfontein: there&rsquo;s a "potential for misdating" when evaluating age based on soil layers and bones. Choice D is incorrect. Text 2 does not state that cosmogenic nuclide dating is applied to the fossils directly but rather to the breccia that surrounds them.</p>$SATQ$, false, 0, $SATQ$OSP-KA-CTC-H007$SATQ$, $SATQ$$SATQ$, $SATQ$8ec4a40c-7861-4021-a17f-d8fe8a73c249$SATQ$::uuid, $SATQ$$SATQ$, $SATQ$proteus$SATQ$, $SATQ$0$SATQ$, NULL, NULL, $SATQ${"questionId":"f3c45b4f","external_id":"1654cd84-f39b-43db-80e8-cf0e6d4b9926","vaultid":"20a4b285-1975-4262-b8c6-7c50dd9fdeb1","uId":"5ba8690f-c709-49f7-bc75-8a2e02b0e310","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"CAS","domain":"Craft and Structure","skill_cd":"CTC","skill_desc":"Cross-Text Connections","difficulty":"H","score_band_range_cd":6,"type":"mcq","stimulus":"<p><strong>Text 1</strong></p>\n<p>Fossils of the hominin <em>Australopithecus africanus</em> have been found in the Sterkfontein Caves of South Africa, but <span style=\"text-decoration: underline;\">assigning an age to the fossils is challenging because of the unreliability of dating methods in this context.</span> The geology of Sterkfontein has caused soil layers from different periods to mix, impeding stratigraphic dating, and dates cannot be reliably imputed from those of nearby animal bones since the bones may have been relocated by flooding.</p>\n<p><strong>Text 2</strong></p>\n<p>Archaeologists used new cosmogenic nuclide dating techniques to reevaluate the ages of <em>A. africanus</em> fossils found in the Sterkfontein Caves. This technique involves analyzing the cosmogenic nucleotides in the breccia&mdash;the matrix of rock fragments immediately surrounding the fossils. The researchers assert that this approach avoids the potential for misdating associated with assigning ages based on Sterkfontein&rsquo;s soil layers or animal bones.</p>","stem":"<p>Based on the texts, how would the researchers in Text 2 most likely respond to the underlined portion in Text 1?</p>","answerOptions":[{"id":"2fdf5c0b-8a9a-44ac-9c9c-3b798f9c9293","content":"<p>They would emphasize the fact that the <em>A. africanus</em> fossils found in the Sterkfontein Caves may have been corrupted in some way over the years.</p>"},{"id":"244034a2-6dc6-4416-90e0-63ec7cc964e0","content":"<p>They would contend that if analyses of surrounding layers and bones in the Sterkfontein Caves were combined, then the dating of the fossils there would be more accurate.&nbsp;</p>"},{"id":"f8beaf83-4f3f-4929-a380-3318aaa9d79b","content":"<p>They would argue that their techniques are better suited than other methods to the unique challenges posed by the Sterkfontein Caves.</p>"},{"id":"ca24f52f-cc02-4735-9bfe-7f3d6a748c37","content":"<p>They would claim that cosmogenic nuclide dating is reliable in the context of the Sterkfontein Caves because it is applied to the fossils directly.</p>"}],"keys":["f8beaf83-4f3f-4929-a380-3318aaa9d79b"],"correct_answer":["C"],"rationale":"<p>Choice C is the best answer. Text 2 states that the researchers used cosmogenic nuclide dating to \"avoid the potential for misdating\" caused by the geology of Sterkfontein, which Text 1 describes as \"challenging\" and unreliable.</p><p>Choice A is incorrect. Neither text suggests that the <em>A.</em> <em>africanus</em> fossils have been \"corrupted,\" but only that traditional dating methods are difficult in Sterkfontein because of floods and soil mixing where the fossils were found. Nothing is implied to have compromised the fossils themselves. Choice B is incorrect. This choice misreads Text 2. Text 2 agrees that stratigraphy and other methods are prone to error in the context of Sterkfontein: there&rsquo;s a \"potential for misdating\" when evaluating age based on soil layers and bones. Choice D is incorrect. Text 2 does not state that cosmogenic nuclide dating is applied to the fossils directly but rather to the breccia that surrounds them.</p>","parenttemplatename":"OSP-KA-CTC-H007","parenttemplateid":"","templateclusterid":"8ec4a40c-7861-4021-a17f-d8fe8a73c249","templateclustername":"","origin":"proteus","position":"0","createDate":1691007959365,"updateDate":1691007959365}$SATQ$::jsonb, 1691007959365, 1691007959365),
    ($SATQ$f3fac04f$SATQ$, $SATQ$d9aeeac9-0ed0-4fd1-83af-365e28e781a0$SATQ$::uuid, $SATQ$e7f5159c-c73c-4aa4-8778-10bff3e4953b$SATQ$::uuid, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Craft and Structure$SATQ$, $SATQ$CAS$SATQ$, $SATQ$WIC$SATQ$, $SATQ$Words in Context$SATQ$, $SATQ$E$SATQ$, 1, $SATQ$mcq$SATQ$, $SATQ$<p>Bioluminescent beetles called fireflies may seem to create flashes of light randomly, but each species of firefly actually has its own special series of repeated flashes and pauses. These unique <span aria-hidden="true">______</span><span class="sr-only">blank</span> allow fireflies of the same species to find each other.</p>$SATQ$, $SATQ$<p>Which choice completes the text with the most logical and precise word or phrase?</p>$SATQ$, $SATQ$[{"id":"f016aed6-4fa8-4baa-aa64-f6f915b8be7b","content":"<p>quantities&nbsp;</p>"},{"id":"a0c8e875-7aa4-4f1a-9271-5d48df713e00","content":"<p>decorations</p>"},{"id":"180f4983-0473-47bf-b171-24c7824eaee4","content":"<p>patterns</p>"},{"id":"4e74bb4c-bbdc-4624-9398-e68cfec07182","content":"<p>agreements</p>"}]$SATQ$::jsonb, $SATQ$["C"]$SATQ$::jsonb, $SATQ$["180f4983-0473-47bf-b171-24c7824eaee4"]$SATQ$::jsonb, $SATQ$<p>Choice C is the best answer because it most logically completes the text&rsquo;s discussion of the flashes created by fireflies. In this context, &ldquo;patterns&rdquo; means distinct and predictable sequences. The text indicates that although the flashes that fireflies produce appear to occur randomly&mdash;that is, without any particular sequence or rhythm&mdash;each species actually produces its own special series of flashes and pauses. Indeed, these series of flashes are so unique that fireflies can use them to find other members of their species. Therefore, this context supports the idea that fireflies produce flashes in distinct and recognizable patterns. </p><p>Choice A is incorrect because &ldquo;quantities&rdquo; means certain amounts or numbers of something. Although the text discusses how different firefly species produce flashes and pauses in unique sequences that help other members of their species to find them, it doesn&rsquo;t mention the number of flashes that are used in these sequences. Choice B is incorrect because in this context, &ldquo;decorations&rdquo; would mean things that make an object more beautiful. Although it may be reasonable to say that firefly flashes are beautiful, the text focuses on the fact that fireflies use these unique sequences of flashes to find other members of their own species, not that the flashes make fireflies more beautiful. Choice D is incorrect because in this context, &ldquo;agreements&rdquo; would refer to deals that individuals have discussed and come to a consensus about. Since fireflies aren&rsquo;t capable of making such agreements, it wouldn&rsquo;t make sense to use this word to refer to the signals they send each other with their flashes. </p>$SATQ$, false, 0, $SATQ$OSP-013-WIC$SATQ$, $SATQ$$SATQ$, $SATQ$b073cbfd-64b0-43f2-8e21-eadc489c4697$SATQ$::uuid, $SATQ$$SATQ$, $SATQ$proteus$SATQ$, $SATQ$0$SATQ$, NULL, NULL, $SATQ${"questionId":"f3fac04f","external_id":"d9aeeac9-0ed0-4fd1-83af-365e28e781a0","vaultid":"e7f5159c-c73c-4aa4-8778-10bff3e4953b","uId":"30e11a84-7363-4d68-8e09-51ca04383616","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"CAS","domain":"Craft and Structure","skill_cd":"WIC","skill_desc":"Words in Context","difficulty":"E","score_band_range_cd":1,"type":"mcq","stimulus":"<p>Bioluminescent beetles called fireflies may seem to create flashes of light randomly, but each species of firefly actually has its own special series of repeated flashes and pauses. These unique <span aria-hidden=\"true\">______</span><span class=\"sr-only\">blank</span> allow fireflies of the same species to find each other.</p>","stem":"<p>Which choice completes the text with the most logical and precise word or phrase?</p>","answerOptions":[{"id":"f016aed6-4fa8-4baa-aa64-f6f915b8be7b","content":"<p>quantities&nbsp;</p>"},{"id":"a0c8e875-7aa4-4f1a-9271-5d48df713e00","content":"<p>decorations</p>"},{"id":"180f4983-0473-47bf-b171-24c7824eaee4","content":"<p>patterns</p>"},{"id":"4e74bb4c-bbdc-4624-9398-e68cfec07182","content":"<p>agreements</p>"}],"keys":["180f4983-0473-47bf-b171-24c7824eaee4"],"correct_answer":["C"],"rationale":"<p>Choice C is the best answer because it most logically completes the text&rsquo;s discussion of the flashes created by fireflies. In this context, &ldquo;patterns&rdquo; means distinct and predictable sequences. The text indicates that although the flashes that fireflies produce appear to occur randomly&mdash;that is, without any particular sequence or rhythm&mdash;each species actually produces its own special series of flashes and pauses. Indeed, these series of flashes are so unique that fireflies can use them to find other members of their species. Therefore, this context supports the idea that fireflies produce flashes in distinct and recognizable patterns. </p><p>Choice A is incorrect because &ldquo;quantities&rdquo; means certain amounts or numbers of something. Although the text discusses how different firefly species produce flashes and pauses in unique sequences that help other members of their species to find them, it doesn&rsquo;t mention the number of flashes that are used in these sequences. Choice B is incorrect because in this context, &ldquo;decorations&rdquo; would mean things that make an object more beautiful. Although it may be reasonable to say that firefly flashes are beautiful, the text focuses on the fact that fireflies use these unique sequences of flashes to find other members of their own species, not that the flashes make fireflies more beautiful. Choice D is incorrect because in this context, &ldquo;agreements&rdquo; would refer to deals that individuals have discussed and come to a consensus about. Since fireflies aren&rsquo;t capable of making such agreements, it wouldn&rsquo;t make sense to use this word to refer to the signals they send each other with their flashes. </p>","parenttemplatename":"OSP-013-WIC","parenttemplateid":"","templateclusterid":"b073cbfd-64b0-43f2-8e21-eadc489c4697","templateclustername":"","origin":"proteus","position":"0","createDate":1691007959315,"updateDate":1691007959315}$SATQ$::jsonb, 1691007959315, 1691007959315),
    ($SATQ$f4166aae$SATQ$, $SATQ$6e37a2f1-4f0d-4d0f-ac83-abf1598b8a21$SATQ$::uuid, $SATQ$4f6b5053-a794-43a7-971d-cddec817eef2$SATQ$::uuid, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Craft and Structure$SATQ$, $SATQ$CAS$SATQ$, $SATQ$WIC$SATQ$, $SATQ$Words in Context$SATQ$, $SATQ$M$SATQ$, 5, $SATQ$mcq$SATQ$, $SATQ$<p>In addition to being an accomplished psychologist himself, Francis Cecil Sumner was a <span aria-hidden="true">______</span><span class="sr-only">blank</span> increasing the opportunity for Black students to study psychology, helping to found the psychology department at Howard University, a historically Black university, in 1930.</p>$SATQ$, $SATQ$<p>Which choice completes the text with the most logical and precise word or phrase?</p>$SATQ$, $SATQ$[{"id":"370b2259-7d24-42a6-a60a-e87999622bae","content":"<p>proponent of</p>"},{"id":"b331047c-a994-491d-8d24-e64e47145b19","content":"<p>supplement to</p>"},{"id":"dcb2953d-b72e-4f22-9d3e-2548f7f879e0","content":"<p>beneficiary of</p>"},{"id":"0aea7d8a-9ad9-481d-a805-831a9332bd1c","content":"<p>distraction for</p>"}]$SATQ$::jsonb, $SATQ$["A"]$SATQ$::jsonb, $SATQ$["370b2259-7d24-42a6-a60a-e87999622bae"]$SATQ$::jsonb, $SATQ$<p>Choice A is the best answer because it most logically completes the text&rsquo;s discussion of Francis Cecil Sumner. As used in this context, &ldquo;proponent of&rdquo; means supporter of. The text says that Sumner helped to found the psychology department at historically Black Howard University in 1930. This is evidence that Sumner supported increasing the opportunity for Black students to study psychology. </p><p>Choice B is incorrect because the phrase &ldquo;supplement to,&rdquo; or addition to, wouldn&rsquo;t make sense in context. The text discusses Sumner&rsquo;s efforts to increase the number of Black psychology students, but it doesn&rsquo;t make sense to describe him as an addition to his efforts. Choice C is incorrect because Sumner was already an accomplished psychologist himself when he helped to found the Howard University psychology department. While Black students were the beneficiaries of his efforts&mdash;that is, they received help because of his efforts&mdash;it wouldn&rsquo;t make sense in this context to describe Sumner as a &ldquo;beneficiary of&rdquo; opportunities, because he was the one doing the helping. Choice D is incorrect because founding a psychology department at Howard University wouldn&rsquo;t be a &ldquo;distraction for&rdquo; Sumner&rsquo;s aim to increase the opportunity for Black students to study psychology&mdash;that is, it wouldn&rsquo;t be something that draws Sumner&rsquo;s attention away from that goal, but rather the opposite. </p>$SATQ$, false, 0, $SATQ$OSP-913-WIC$SATQ$, $SATQ$$SATQ$, $SATQ$86e7ad36-036e-46dd-8f89-e403058e51ec$SATQ$::uuid, $SATQ$$SATQ$, $SATQ$proteus$SATQ$, $SATQ$0$SATQ$, NULL, NULL, $SATQ${"questionId":"f4166aae","external_id":"6e37a2f1-4f0d-4d0f-ac83-abf1598b8a21","vaultid":"4f6b5053-a794-43a7-971d-cddec817eef2","uId":"cbbf7a78-e5d6-4d90-8325-5ffe4b3e5cae","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"CAS","domain":"Craft and Structure","skill_cd":"WIC","skill_desc":"Words in Context","difficulty":"M","score_band_range_cd":5,"type":"mcq","stimulus":"<p>In addition to being an accomplished psychologist himself, Francis Cecil Sumner was a <span aria-hidden=\"true\">______</span><span class=\"sr-only\">blank</span> increasing the opportunity for Black students to study psychology, helping to found the psychology department at Howard University, a historically Black university, in 1930.</p>","stem":"<p>Which choice completes the text with the most logical and precise word or phrase?</p>","answerOptions":[{"id":"370b2259-7d24-42a6-a60a-e87999622bae","content":"<p>proponent of</p>"},{"id":"b331047c-a994-491d-8d24-e64e47145b19","content":"<p>supplement to</p>"},{"id":"dcb2953d-b72e-4f22-9d3e-2548f7f879e0","content":"<p>beneficiary of</p>"},{"id":"0aea7d8a-9ad9-481d-a805-831a9332bd1c","content":"<p>distraction for</p>"}],"keys":["370b2259-7d24-42a6-a60a-e87999622bae"],"correct_answer":["A"],"rationale":"<p>Choice A is the best answer because it most logically completes the text&rsquo;s discussion of Francis Cecil Sumner. As used in this context, &ldquo;proponent of&rdquo; means supporter of. The text says that Sumner helped to found the psychology department at historically Black Howard University in 1930. This is evidence that Sumner supported increasing the opportunity for Black students to study psychology. </p><p>Choice B is incorrect because the phrase &ldquo;supplement to,&rdquo; or addition to, wouldn&rsquo;t make sense in context. The text discusses Sumner&rsquo;s efforts to increase the number of Black psychology students, but it doesn&rsquo;t make sense to describe him as an addition to his efforts. Choice C is incorrect because Sumner was already an accomplished psychologist himself when he helped to found the Howard University psychology department. While Black students were the beneficiaries of his efforts&mdash;that is, they received help because of his efforts&mdash;it wouldn&rsquo;t make sense in this context to describe Sumner as a &ldquo;beneficiary of&rdquo; opportunities, because he was the one doing the helping. Choice D is incorrect because founding a psychology department at Howard University wouldn&rsquo;t be a &ldquo;distraction for&rdquo; Sumner&rsquo;s aim to increase the opportunity for Black students to study psychology&mdash;that is, it wouldn&rsquo;t be something that draws Sumner&rsquo;s attention away from that goal, but rather the opposite. </p>","parenttemplatename":"OSP-913-WIC","parenttemplateid":"","templateclusterid":"86e7ad36-036e-46dd-8f89-e403058e51ec","templateclustername":"","origin":"proteus","position":"0","createDate":1691007959354,"updateDate":1691007959354}$SATQ$::jsonb, 1691007959354, 1691007959354),
    ($SATQ$f52cc78c$SATQ$, $SATQ$e7659f22-d958-498c-a061-23d58d11b7b3$SATQ$::uuid, $SATQ$4bb06f21-f0ac-4f4f-8d2a-a678665eb728$SATQ$::uuid, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Craft and Structure$SATQ$, $SATQ$CAS$SATQ$, $SATQ$CTC$SATQ$, $SATQ$Cross-Text Connections$SATQ$, $SATQ$M$SATQ$, 4, $SATQ$mcq$SATQ$, $SATQ$<p>Text 1</p>
<p>Polar bears sustain themselves primarily by hunting seals on the Arctic sea ice, but rising ocean temperatures are causing the ice to diminish, raising concerns about polar bear population declines as these large predators&rsquo; seal-hunting habitats continue to shrink. A 2020 study examining polar bear populations across the Arctic <u>concluded that populations affected by sea-ice loss are at great risk of extinction by the end of the twenty-first century</u>.</p>
<p>Text 2</p>
<p>Monitoring carried out by researchers from the Norwegian Polar Institute shows that the polar bear population on the Arctic archipelago of Svalbard remains stable and well nourished despite rapidly declining sea ice in recent years. The researchers attribute this population&rsquo;s resilience in part to a shift in feeding strategies: in addition to hunting seals, the Svalbard polar bears have begun relying on a diet of reindeer meat and birds&rsquo; eggs.</p>$SATQ$, $SATQ$<p>Based on the texts, how would the researchers in Text 2 most likely respond to the conclusion presented in the underlined portion of Text 1?</p>$SATQ$, $SATQ$[{"id":"c6b11a17-e42a-49bc-9b56-18fd680b3f77","content":"<p>By noting that it neglects the possibility of some polar bear populations adapting to changes in their environment</p>"},{"id":"c4bbef8b-aa39-4557-b869-3945659c0ab8","content":"<p>By suggesting that it is likely incorrect about the rates at which warming ocean temperatures have caused sea ice to melt in the Arctic</p>"},{"id":"55e88bd7-6a3b-4406-b538-8a6206cafba9","content":"<p>By asserting that it overlooks polar bear populations that have not yet been affected by loss of seal-hunting habitats</p>"},{"id":"396b2c97-db98-4e9c-a722-2db6b9ae58d6","content":"<p>By arguing that it fails to account for polar bears&rsquo; reliance on a single seal-hunting strategy</p>"}]$SATQ$::jsonb, $SATQ$["A"]$SATQ$::jsonb, $SATQ$["c6b11a17-e42a-49bc-9b56-18fd680b3f77"]$SATQ$::jsonb, $SATQ$<p>Choice A is the best answer. Text 2 describes how the Svalbard polar bears have adapted to the loss of sea ice by diversifying their diet and feeding on reindeer and seabird eggs, resulting in a &ldquo;stable and well nourished&rdquo; population despite environmental challenges. This counters the underlined claim that polar bears facing a loss of sea ice are at &ldquo;great risk of extinction&rdquo; by the end of the century. </p><p>Choice B is incorrect. Text 2 does not challenge the fact that sea ice is rapidly declining in the Arctic due to warming ocean temperatures. In fact, it states that the Svalbard polar bears have faced &ldquo;rapidly declining sea ice in recent years.&rdquo; Choice C is incorrect. The claim in Text 1 is specific to polar bear populations affected by the loss of seal hunting habitats, so unaffected populations are irrelevant to the claim. Also, Text 2 doesn&rsquo;t mention any polar bear populations that haven&rsquo;t yet been affected by loss of seal hunting habitats. It focuses on a population that has been affected by sea-ice loss but has managed to survive and thrive nevertheless. Choice D is incorrect. Text 2 doesn&rsquo;t imply that polar bears rely on a single seal-hunting strategy. In fact, the researcher in Text 2 would say that Text 1 fails to account for polar bears&rsquo; ability to develop other hunting strategies and food sources. </p>$SATQ$, false, 0, $SATQ$OSP-KA-CTC-M009$SATQ$, $SATQ$$SATQ$, $SATQ$4266494f-ca30-44ff-b2d6-52eb4253374d$SATQ$::uuid, $SATQ$$SATQ$, $SATQ$proteus$SATQ$, $SATQ$0$SATQ$, NULL, NULL, $SATQ${"questionId":"f52cc78c","external_id":"e7659f22-d958-498c-a061-23d58d11b7b3","vaultid":"4bb06f21-f0ac-4f4f-8d2a-a678665eb728","uId":"fb76681d-c13d-4ed1-a221-37e988949fc8","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"CAS","domain":"Craft and Structure","skill_cd":"CTC","skill_desc":"Cross-Text Connections","difficulty":"M","score_band_range_cd":4,"type":"mcq","stimulus":"<p>Text 1</p>\n<p>Polar bears sustain themselves primarily by hunting seals on the Arctic sea ice, but rising ocean temperatures are causing the ice to diminish, raising concerns about polar bear population declines as these large predators&rsquo; seal-hunting habitats continue to shrink. A 2020 study examining polar bear populations across the Arctic <u>concluded that populations affected by sea-ice loss are at great risk of extinction by the end of the twenty-first century</u>.</p>\n<p>Text 2</p>\n<p>Monitoring carried out by researchers from the Norwegian Polar Institute shows that the polar bear population on the Arctic archipelago of Svalbard remains stable and well nourished despite rapidly declining sea ice in recent years. The researchers attribute this population&rsquo;s resilience in part to a shift in feeding strategies: in addition to hunting seals, the Svalbard polar bears have begun relying on a diet of reindeer meat and birds&rsquo; eggs.</p>","stem":"<p>Based on the texts, how would the researchers in Text 2 most likely respond to the conclusion presented in the underlined portion of Text 1?</p>","answerOptions":[{"id":"c6b11a17-e42a-49bc-9b56-18fd680b3f77","content":"<p>By noting that it neglects the possibility of some polar bear populations adapting to changes in their environment</p>"},{"id":"c4bbef8b-aa39-4557-b869-3945659c0ab8","content":"<p>By suggesting that it is likely incorrect about the rates at which warming ocean temperatures have caused sea ice to melt in the Arctic</p>"},{"id":"55e88bd7-6a3b-4406-b538-8a6206cafba9","content":"<p>By asserting that it overlooks polar bear populations that have not yet been affected by loss of seal-hunting habitats</p>"},{"id":"396b2c97-db98-4e9c-a722-2db6b9ae58d6","content":"<p>By arguing that it fails to account for polar bears&rsquo; reliance on a single seal-hunting strategy</p>"}],"keys":["c6b11a17-e42a-49bc-9b56-18fd680b3f77"],"correct_answer":["A"],"rationale":"<p>Choice A is the best answer. Text 2 describes how the Svalbard polar bears have adapted to the loss of sea ice by diversifying their diet and feeding on reindeer and seabird eggs, resulting in a &ldquo;stable and well nourished&rdquo; population despite environmental challenges. This counters the underlined claim that polar bears facing a loss of sea ice are at &ldquo;great risk of extinction&rdquo; by the end of the century. </p><p>Choice B is incorrect. Text 2 does not challenge the fact that sea ice is rapidly declining in the Arctic due to warming ocean temperatures. In fact, it states that the Svalbard polar bears have faced &ldquo;rapidly declining sea ice in recent years.&rdquo; Choice C is incorrect. The claim in Text 1 is specific to polar bear populations affected by the loss of seal hunting habitats, so unaffected populations are irrelevant to the claim. Also, Text 2 doesn&rsquo;t mention any polar bear populations that haven&rsquo;t yet been affected by loss of seal hunting habitats. It focuses on a population that has been affected by sea-ice loss but has managed to survive and thrive nevertheless. Choice D is incorrect. Text 2 doesn&rsquo;t imply that polar bears rely on a single seal-hunting strategy. In fact, the researcher in Text 2 would say that Text 1 fails to account for polar bears&rsquo; ability to develop other hunting strategies and food sources. </p>","parenttemplatename":"OSP-KA-CTC-M009","parenttemplateid":"","templateclusterid":"4266494f-ca30-44ff-b2d6-52eb4253374d","templateclustername":"","origin":"proteus","position":"0","createDate":1691007959366,"updateDate":1691007959366}$SATQ$::jsonb, 1691007959366, 1691007959366),
    ($SATQ$f61c22f3$SATQ$, $SATQ$cdea167b-1a74-40c4-8d5c-8ac7df6c79cb$SATQ$::uuid, NULL, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Craft and Structure$SATQ$, $SATQ$CAS$SATQ$, $SATQ$TSP$SATQ$, $SATQ$Text Structure and Purpose$SATQ$, $SATQ$H$SATQ$, 7, $SATQ$mcq$SATQ$, $SATQ$<p>Changes to vegetation cover and other human activities influence carbon and nitrogen levels in soil, though how deep these effects extend is unclear. Hypothesizing that differences in land use lead to differences in carbon and nitrogen levels that are not restricted to the topsoil layer (0&ndash;30 cm deep), Chukwuebuka Okolo and colleagues sampled soils across multiple land-use types (e.g., grazing land, cropland, forest) within each of several Ethiopian locations. They found, though, that across land-use types, carbon and nitrogen decreased to comparably low levels beyond depths of 30 cm.</p>$SATQ$, $SATQ$<p>Which choice best describes the overall structure of the text?</p>$SATQ$, $SATQ$[{"id":"2a5a8582-4e3f-4187-8b39-7438ddc27c6c","content":"<p>It describes a phenomenon that scientists do not fully understand, explains a research team&rsquo;s hypothesis about that phenomenon, and then describes a finding that led the team to refine the hypothesis.&nbsp;</p>"},{"id":"cee59cde-822d-4607-82d0-bf9753acf39f","content":"<p>It introduces an unresolved scientific question, presents a research team&rsquo;s hypothesis pertaining to that question, and then describes an observation made by the team that conflicts with that hypothesis.&nbsp;</p>"},{"id":"e1744ebc-fbed-4802-b8fd-8c0e9aa4c8b5","content":"<p>It discusses a process that scientists are somewhat unclear about, introduces competing hypotheses about that process, and then explains how a research team concluded that one of those hypotheses is likely correct.</p>"},{"id":"afe020c6-3cb0-468c-802a-159e6b8b1934","content":"<p>It explains a hypothesis that has been the subject of scientific debate, discusses how a research team tested that hypothesis, and then presents data the team collected that validate the hypothesis.</p>"}]$SATQ$::jsonb, $SATQ$["B"]$SATQ$::jsonb, $SATQ$["cee59cde-822d-4607-82d0-bf9753acf39f"]$SATQ$::jsonb, $SATQ$<p>Choice B is the best answer because it most accurately describes the overall structure of the text. The text begins by explaining that human activities influence carbon and nitrogen levels in soil, but how deeply these effects are seen in the soil remains an unresolved question. Next, the text summarizes Okolo and colleagues&rsquo; hypothesis regarding this question&mdash;which is that the different effects on carbon and nitrogen levels associated with different types of land use would also be observed below the topsoil layer&mdash;and then briefly explains the methods they used to test this hypothesis. Finally, the text states that the researchers found that at depths below the topsoil layer, carbon and nitrogen decreased to similarly low levels across all land-use types, a finding that conflicts with the team&rsquo;s hypothesis presented earlier in the text. Thus, the text introduces an unresolved scientific question, presents a research team&rsquo;s hypothesis pertaining to that question, and then describes an observation that the team made that conflicted with their hypothesis.</p><p>Choice A is incorrect. Although the text introduces a phenomenon (the fact that human activities influence carbon and nitrogen levels in the soil) that isn&rsquo;t fully understood by scientists and explains a research team&rsquo;s hypothesis about the phenomenon, the text doesn&rsquo;t describe how the team refined their hypothesis when a research finding contradicted it. Choice C is incorrect because the text doesn&rsquo;t discuss a process at all; rather, it poses an unsolved scientific question and presents a hypothesis that Okolo and colleagues tested to answer that question. Moreover, the text only describes one hypothesis; it doesn&rsquo;t mention any competing hypotheses, nor does it suggest that Okolo&rsquo;s team was able to determine which hypothesis was correct. Choice D is incorrect because the text doesn&rsquo;t begin by presenting a hypothesis that is under scientific debate; rather, it presents a question that scientists have been unable to answer and then introduces a hypothesis formulated by Okolo and colleagues. While the text does explain how Okolo&rsquo;s team tested their hypothesis, the text goes on to say that their data conflicted with their hypothesis, not that the data validated, or supported, their hypothesis.</p>$SATQ$, false, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, $SATQ${"questionId":"f61c22f3","external_id":"cdea167b-1a74-40c4-8d5c-8ac7df6c79cb","vaultid":null,"uId":"4e03d824-fe3e-4523-9cd5-e6c43ba07526","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"CAS","domain":"Craft and Structure","skill_cd":"TSP","skill_desc":"Text Structure and Purpose","difficulty":"H","score_band_range_cd":7,"type":"mcq","stimulus":"<p>Changes to vegetation cover and other human activities influence carbon and nitrogen levels in soil, though how deep these effects extend is unclear. Hypothesizing that differences in land use lead to differences in carbon and nitrogen levels that are not restricted to the topsoil layer (0&ndash;30 cm deep), Chukwuebuka Okolo and colleagues sampled soils across multiple land-use types (e.g., grazing land, cropland, forest) within each of several Ethiopian locations. They found, though, that across land-use types, carbon and nitrogen decreased to comparably low levels beyond depths of 30 cm.</p>","stem":"<p>Which choice best describes the overall structure of the text?</p>","answerOptions":[{"id":"2a5a8582-4e3f-4187-8b39-7438ddc27c6c","content":"<p>It describes a phenomenon that scientists do not fully understand, explains a research team&rsquo;s hypothesis about that phenomenon, and then describes a finding that led the team to refine the hypothesis.&nbsp;</p>"},{"id":"cee59cde-822d-4607-82d0-bf9753acf39f","content":"<p>It introduces an unresolved scientific question, presents a research team&rsquo;s hypothesis pertaining to that question, and then describes an observation made by the team that conflicts with that hypothesis.&nbsp;</p>"},{"id":"e1744ebc-fbed-4802-b8fd-8c0e9aa4c8b5","content":"<p>It discusses a process that scientists are somewhat unclear about, introduces competing hypotheses about that process, and then explains how a research team concluded that one of those hypotheses is likely correct.</p>"},{"id":"afe020c6-3cb0-468c-802a-159e6b8b1934","content":"<p>It explains a hypothesis that has been the subject of scientific debate, discusses how a research team tested that hypothesis, and then presents data the team collected that validate the hypothesis.</p>"}],"keys":["cee59cde-822d-4607-82d0-bf9753acf39f"],"correct_answer":["B"],"rationale":"<p>Choice B is the best answer because it most accurately describes the overall structure of the text. The text begins by explaining that human activities influence carbon and nitrogen levels in soil, but how deeply these effects are seen in the soil remains an unresolved question. Next, the text summarizes Okolo and colleagues&rsquo; hypothesis regarding this question&mdash;which is that the different effects on carbon and nitrogen levels associated with different types of land use would also be observed below the topsoil layer&mdash;and then briefly explains the methods they used to test this hypothesis. Finally, the text states that the researchers found that at depths below the topsoil layer, carbon and nitrogen decreased to similarly low levels across all land-use types, a finding that conflicts with the team&rsquo;s hypothesis presented earlier in the text. Thus, the text introduces an unresolved scientific question, presents a research team&rsquo;s hypothesis pertaining to that question, and then describes an observation that the team made that conflicted with their hypothesis.</p><p>Choice A is incorrect. Although the text introduces a phenomenon (the fact that human activities influence carbon and nitrogen levels in the soil) that isn&rsquo;t fully understood by scientists and explains a research team&rsquo;s hypothesis about the phenomenon, the text doesn&rsquo;t describe how the team refined their hypothesis when a research finding contradicted it. Choice C is incorrect because the text doesn&rsquo;t discuss a process at all; rather, it poses an unsolved scientific question and presents a hypothesis that Okolo and colleagues tested to answer that question. Moreover, the text only describes one hypothesis; it doesn&rsquo;t mention any competing hypotheses, nor does it suggest that Okolo&rsquo;s team was able to determine which hypothesis was correct. Choice D is incorrect because the text doesn&rsquo;t begin by presenting a hypothesis that is under scientific debate; rather, it presents a question that scientists have been unable to answer and then introduces a hypothesis formulated by Okolo and colleagues. While the text does explain how Okolo&rsquo;s team tested their hypothesis, the text goes on to say that their data conflicted with their hypothesis, not that the data validated, or supported, their hypothesis.</p>","parenttemplatename":null,"parenttemplateid":null,"templateclusterid":null,"templateclustername":null,"origin":null,"position":null,"createDate":1730147323040,"updateDate":1730147323040}$SATQ$::jsonb, 1730147323040, 1730147323040)
